-- GENERATED by `wfj generate` from data/quest/quest-0096.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [96003] = { "悪意ある者を引きずり下ろす", "Bethra'zelとMazzogoreにEye of Endless Influenceを使ってその力を吸い取り、とどめを刺す。", "思ったとおり、器は融合して新しい何かになった。強力な何かにな。\n\n器が蓄えた力を捕らえるのなら、その力を我々に有利に使う方法があるはずだ。フェルのアーティファクトが安全なことも手に入りやすいこともめったにないが、せっかくだから何かに使ってみようじゃないか、ん？\n\n実地試験の時間だ。\n\nこの結晶を持って、Bethra'zelとMazzogoreに使え。奴らの最も強力な悪魔の2体だ。奴らがいるだけで野営地の守りは固い。それを変えられるか見てみよう。", nil, nil, 0x7aac2899, 0x8889e560, 0x8e5adb4b, nil, nil, "...mm" },
  [96009] = { "危険な賭け", "Farholde KeepにいるBertrand Ironbrowのために、Turner's Logging CampからWood Bundleを$N1個集める。", "いつまでも驚かされっぱなしのことが1つある。人間の意欲ってやつだ。オークや教団員がうようよしとる荒れ果てた戦場を見て、店を構えるのにうってつけの場所だと考えるんだからな！大したもんだ。\n\nだが、どこに建てるか教えるのはわしの仕事じゃない。建て方を見せてやるだけだ。そして、この砦を連中の言うほど大きくしたけりゃ、woodがたくさん要る。\n\n道がこれだけ危なくなっちまったせいで、北西の製材所からの材木の輸送は、這うような遅さになっとる。bundlesをいくつか取ってきてくれんか？", nil, nil, 0xf67b5cb7, 0xa8b5ecb8, 0x2d0a032b, nil, nil, "...mm" },
  [96010] = { "パイロンの破片", "MagramとGelkisの村で守られているパイロンの欠片と破片を取り戻す。それらをMordent Evenshadeのところへ持ち帰る。", "両方のパイロンの損傷は、暴れ回る無謀なcentaurのせいだと考えてまず間違いないでしょう。ですが、彼らが暴れた時機のせいで、欠片が離れ離れになってしまったのではないかと思うのです。彼らの争いについてはほとんど知りませんが、少なくとも2つの主な勢力がShen'dralasに侵入したことは知っています。獰猛なMagramと、狡猾なGelkisです。\n\nこのような宝を戦場の真っ只中に置いておくのは賢明ではありません。今頃はもう、彼らは戦利品をそれぞれの村へ持ち帰ったものと思われます。", nil, nil, 0x23e961a4, 0x95e79125, 0x53c5a4fd, nil, nil, "...mm" },
  [96015] = { "鉱夫の問題", "Sergeant Riftanのために、Twilight's Shroud近くの洞窟でOgre Minerを$N1体とTwilight Subjugatorを$N2体倒す。", "敵が愚かであることに感謝すべきだな。ogreの軍を自由に使えるというのに、Twilight's Hammerは奴らを戦場から遠く離れた鉱山で働かせている。管理のまずさなのか内輪もめなのかはわからんが、いずれにせよ奴らは身を守れる状態ではない。\n\nそこで我々の出番だ。教団の注意が分散している今、弱っている敵を叩き、さらに分断する好機だ。この鉱山へ行き、奴らの隊列に混乱をまき散らしてこい。", nil, nil, 0x39bbf3f5, 0xdc1ffb67, 0xae3ba2da, nil, nil, "...mm" },
  [96016] = { "嵐の武器", "Eye of the TempestをAlterac MountainsのBath'rah the Windwatcherに届ける。", "よくやったな。お前さんが報酬を欲しくてうずうずしとるのは分かる。すまんが、わしはあまり物を持っとるドワーフじゃなくてな。\n\n<Veyricは辺鄙な居場所を大きく身振りで示した。>\n\nだが、こうしよう。Alterac MountainsにWindwatcherというトロールが住んどると聞く。あいつ自身も強力なシャーマンで、嵐のエレメンタルの専門家だ。そのエレメンタルの核をあいつのところへ持っていけば、お前さんの勝利にふさわしい武器を作ってくれるはずだ。", nil, nil, 0x578d0b90, 0x5da19497, 0x67a5ea2f, nil, nil, "...mm" },
  [96018] = { "パイロンに力を", "Shen'dralasの神殿内からMana Sieveを手に入れ、それを使ってAncient Mana Crystalを集める。十分なマナを集めたら、パイロンに力を注ぎ、Mordent Evenshadeのところへ戻る。", "Shen'dralasのあちこちに漂うマナの火花を見かけたかもしれません。これは新しい現象で、おそらくパイロンが受けた損傷の結果でしょう。\n\nこのマナを半結晶の形で取り戻す必要があります。それには神殿の中にあるMana Sieveを使えばよいのです。sieveを借りて、見つけた浮遊するマナの球をすべて集めてください。\n\n神殿の住人たちは、大切な遺物を許可なく借りられることを快く思わないでしょうが、いずれはわかってくれるはずです。", nil, nil, 0x877d1e35, 0x9ac2fffe, 0xcb0a6ad5, nil, nil, "...mm" },
  [96025] = { "一直線に", "Hyjalの山頂でElaenaの友と会う。", "助けてくれてありがとう、{name}。私の大切な友人が、頂上であなたの到着を待っています。\n\n東へ道を登っていけば彼女に会えますよ。", nil, nil, 0xca8d1b90, 0xed856e93, 0xf8757673, nil, nil, "...mm" },
  [96026] = { "第二段階：さらに石を", "Heavy Weightstoneを$N1個、Bolder'okにいるHamurに届ける。", "これ、いい石。でも仕上げ、いる。もっと石。\n\n石を強くできる、石だけ。それ、石のやり方。\n\nおれ、ちびどもがすごく重い石つくるの見た。重い石持ってこい、おれ武器つくる。", nil, nil, 0xfeb09358, 0xba014bbc, 0x879784af, nil, nil, "...mm" },
  [96031] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、IronforgeのGretta Finespindleと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", nil, nil, 0x40d05936, 0x444c023e, 0x86e620e9, nil, nil, "...mm" },
  [96044] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、KharanosのTognus Flintfireと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", nil, nil, 0x16979ea3, 0xcccec145, 0x469a706e, nil, nil, "...mm" },
  [96045] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、IronforgeのVosur Brakthelと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Alchemyを始めたんなら、少し覚えたところで、野営地用のMana Wellの作り方も教えてやれるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, nil, 0x32f4ba12, 0xfd210ba1, 0xd857517b, nil, nil, "...mm" },
  [96046] = { "キャンプ101：Mining", "スキルの熟練を示したら、KharanosのYarr Hammerstoneと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", nil, nil, 0xa8fe12f3, 0xc44564fc, 0x8ef0fff6, nil, nil, "...mm" },
  [96047] = { "キャンプ101：First Aid", "スキルの熟練を示したら、KharanosのThamner Polと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", nil, "さあ、これで自分だけのFirst Aid Kitを作れるようになったよ。町の真ん中に野営地を設けられるのを好む人はあまりいないから、試してみたいなら荒野へ出かけるといい。\n\nああ、それと覚えておいてくれ。焚き火なしでは野営地は完成しない。野営地を始める前に、焚き火がひとつ必要になる。たいていの料理人なら火のおこし方を教えてくれるよ。まだなら、料理の技を教えてくれる人のところへ行って、基本を学んでおくといいかもしれないね。", 0x6e7c255b, 0xdf8f53b4, 0x32ff3188, nil, 0x3a282524, "...m." },
  [96050] = { "キャンプ101：Fishing", "スキルの熟練を示したら、Dun MoroghのIceflow Lake付近にいるPaxton Ganterと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", nil, "これで、自分だけのFish Bowlを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xe0c1c700, 0x475dee95, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [96055] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、IronforgeのReyna Stonebranchと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, "これで、自分だけのIncense Candleを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xd7cde71c, 0x8a8b95de, 0xe0048777, nil, 0x52608ebe, "...m." },
  [96056] = { "キャンプ101：Skinning", "スキルの熟練を示したら、IronforgeのBalthus Stoneflayerと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", nil, nil, 0x14236b38, 0x9b6727a8, 0x1755b1ba, nil, nil, "...mm" },
  [96057] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、IronforgeのUthrar Threxと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, "これで、自分だけのRallying Bannerを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xde7f398c, 0xf651cfe5, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [96058] = { "キャンプ101：Engineering", "スキルの熟練を示したら、KharanosのBronk Guzzlegearと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "あんたみたいなエンジニアは、面白半分にも儲けのためにも、あらゆる部品やボットや爆弾をこしらえられるんだよな。\n\n野営地用のReagent Botの作り方を教えてくれる奴を知ってるよ。この便利な自動人形が物資を切らさないようにしてくれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはなくなるさ。", nil, nil, 0x1cb4025b, 0x1d43c051, 0x549b28c0, nil, nil, "...mm" },
  [96059] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、IronforgeのThonys Pillarstoneと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターへの道を歩み始めたんなら、コツを覚えたところで、野営地用のEnchanted Luteの作り方を教えてやれると思うよ。\n\n暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0xa6eed0e9, 0x4457b10b, nil, nil, "...mm" },
  [96060] = { "抑えた期待", "Phantasmal Bladeを使ってShen'dralasの野生動物を$N1体処刑し、神殿のVindaelのもとへ戻る。", "まず言わせてもらうが、私は生前、剣の達人だった。昼は武器を鍛え、夜はそれを振るったものだ。\n\n君もよく承知のとおり、この剣と私の関係は今では実にややこしい。振り回すくらいはできると思うが、ほかの霊と戦うのでもなければ大して役に立つとは思えない。それがShen'dralasにいる私にとって、本当に何かの価値があるだろうか？\n\nそれでも、この剣の力を試してほしいのだ。それに、我々の森も少し穏やかに間引いてやってもいいだろう。", nil, nil, 0x7a691a0d, 0x9f7235cd, 0x7fdbbf59, nil, nil, "...mm" },
  [96063] = { "気体の黄金", "Sleebo Fizzlespoutのために、Marsh Gas Vialを5個集める。", "未来の燃料は石炭でも石油でもない、ガスなんだよ、ベイビー！南西の沼の池じゃ、そいつがトン単位で噴き出してるし、それを役立てるうってつけの発明もある。そのガスで動く新型のエンジンさ。ただ、ガスを集めるのが本当に厄介でね。\n\n科学と産業の未来にささやかな貢献をしてみようって気があるなら、そのガスを少し集めるのを手伝ってくれないか？水辺の噴出口から湧き上がってるのが見えるはずだよ。", nil, nil, 0x15fabd2d, 0x1d9e7859, 0xb3c1cb4c, nil, nil, "...mm" },
  [96067] = { "揺さぶって殴れ", "Sleeboの発明品のテストを手伝う。", "ここにいる私の機械の相棒、G45-B4Gにはもう気づいたかもしれないね。あいつの麻布の胸の中でぐるぐる回ってるのが、私のガス駆動エンジンの、唯一無二の、動く試作品なんだ。\n\nそろそろ負荷試験が必要だと思ってね。あいつと一戦交えてみないか？君が集めてくれたガスで、あいつをパワーアップさせられるよ。\n\nああ、それと、あいつを傷つけるなんて心配はいらない。何も感じないからね！", nil, nil, 0x92a61d66, 0x8ec7f3bb, 0x2c61205f, nil, nil, "...mm" },
  [96076] = { "需要あり - 古代エルフの珍品", "Dire Maulへ行き、Alzzin the WildshaperからFelvine Seedを、Prince TortheldrinからAncient Mementoを、King GordokからEarthstone Diamond Pinky Ringを手に入れ、Booty BayのPix Xizzixのもとへ持っていく。", "私の雇い主たちは、廃墟となったエルフの都市Eldre'Thalas、今ではDire Maulとして知られる場所から、魔法の珍品を手に入れたがっている。何かの魔法の研究らしい。いずれにせよ、これらの品を手に入れてくれれば、たっぷり報酬を出せる。\n\n東翼のAlzzin the WildshaperからFelvine Seedを、西翼のPrince TortheldrinからAncient Mementoを、北翼のKing GordokからEarthstone Diamond Pinky Ringを取ってきてくれ。", nil, nil, 0x71524e47, 0xcc43b67e, 0x6a92f373, nil, nil, "...mm" },
  [96077] = { "Belleの指輪", "指輪をElwynn ForestのLion's Pride InnにいるMichelle Belleのもとへ届ける。", "ああ、Thomas Belleか。\n\n<Daythorの様子が急に変わり、その人物の懐かしい思い出を呼び起こしているかのようだ。>\n\nThomasは、Scourgeが我々の前哨地を包囲したとき、最初に倒れたひとりだった。戦いが終わるまで、彼が死んだことは知らなかった。悲劇だ……実に将来有望な若者だったのに。\n\nこれは彼の愛するMichelleに届けるのが筋だろうな。記憶が正しければ、彼はよくGoldshireの話をしていた。", nil, nil, 0x70873c99, 0x6914e5b6, 0x91c0bc02, nil, nil, "...mm" },
  [96078] = { "焚き火を囲んで語られた物語", "石板の拓本をDurotarのSen'jin VillageにいるMaster Gadrinのところへ持って行く。", "{name}、我らDarkspearは、伝統の多くを口伝えの語りによって守り続けている。こうした伝説を次の世代へと伝え、教えを説き、子らに戒めの物語を紡いで聞かせるのだ。\n\nこの拓本は、我らの霊的指導者であるSen'jin VillageのMaster Gadrinのもとへ届けねばならない。彼はDarkspearで最も賢い者の一人であり、この物語の真実を聞きたいと望むだろう。\n\nお前のためにも、この物語の写しをもう一部用意しておいた。もし失くすことがあれば、わずかな手数料でまた作ってやろう。", nil, nil, 0xab004595, 0x10eeb9cc, 0x5a70044a, nil, nil, "...mm" },
  [96081] = { "傷の包帯", "Farholde KeepにいるBrother Lowleyのために、Mageweave Clothを20枚集める。", "戦う軍勢がいつも必要とするものが一つあるとすれば、それは包帯です。残念ながら、Farholdeには布を安定して作る手段がありません。そのため、ゴブリンからの輸入に頼るか、運が良ければオークから奪い返したもので賄っています。\n\n今、上質な布の蓄えが底をつきかけています。このままでは、じきに古いシャツで包帯を作り始めなければならないでしょう。もし私たちを助ける手立てがあるなら、多くの命を救うことになります。", nil, nil, 0xa013f7ac, 0x6907c997, 0xf5682b7a, nil, nil, "...mm" },
  [96082] = { "医師の助手", "Brother Lowleyのために、Wounded Soldierを3人、包帯で手当てする。", "いただいた布は私が包帯に仕立てます。その間に、すでに作ってあるこちらの包帯を持っていって、手当てが必要な兵士たちの傷に巻いてあげてください。基本的な応急手当で済むはずです。\n\nここでのあなたの助けは必要不可欠ですし、心から感謝しています。私はどうしても、一度にあちこちにはいられませんから。", nil, nil, 0x813c39d3, 0xd861f5a5, 0x639e062f, nil, nil, "...mm" },
  [96083] = { "聖職者の隔離所", "Farholde Keepの礼拝堂にいるSister Rowlandと話す。", "今のところ、ここでできることはすべてやってくれました。\n\nさらに力を貸してくださるなら、丘を登って礼拝堂へ行ってください。本堂の外にある、小さい方の建物です。\n\nそこではSister Rowlandが、原因不明の病にかかって隔離された兵士たちを何人か看ています。", nil, nil, 0x04053102, 0xcd5704ef, 0x124e53da, nil, nil, "...mm" },
  [96084] = { "水に何かがいる", "Farholde Keepの礼拝堂にいるSister Rowlandのために、平原から飲み水のサンプルを採取する。", "生々しい詳細は省きますが、この兵士たちはひどく病んでいます。症状の性質から考えて、食べ物か水のどちらかに問題があるのだと思います。\n\n近くの農場から入ってくる作物はもう調べましたから、残るは地元の川から引いている水だけです。試料を採るのに一番良い場所は、北の平原にある池です。ほとんどすべての川がその一帯を流れていますから、そこで汚染がないか調べるのが賢明でしょう。", nil, nil, 0xc9842e6c, 0x8ac004f6, 0x14f3164a, nil, nil, "...mm" },
  [96085] = { "上流の汚染", "飲み水を汚染している生き物を見つけ出して始末する。その後、Farholde Keepの礼拝堂にいるSister Rowlandのところへ戻る。", "この試料の不純物は、有機的なもののようです。排泄物とまでは言えませんが、何か毒性のあるものなのは確かです。\n\n私は野生生物には詳しくありませんが、上流に何かがいて、それが水を汚染しているのではないかと思います。何かの動物か、少なくとも何らかの生き物でしょう。\n\n川をできるだけ北までたどって、原因を突き止められるか見てきてください。もし動物なら、始末しなければなりません。ここFarholdeにいる皆の安全のためです。", nil, nil, 0x70e2ad07, 0xc2fea7b0, 0x1bb9e62f, nil, nil, "...mm" },
  [96101] = { "大自然", "Raan's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "ごきげんよう、{class}。あなたは冒険者らしい顔つきをしているな。それはいいことだ。世の中には、富と栄光を求める私たちのような落ち着きのない者がもっと必要なのだ。\n\nこの稼業で成功するには、荒野で生き抜く術を身につけなければならない。あなたの野外の技がどれほどかは知らないが、学ぶ気があるなら、ひとつふたつ教えられるだろう。\n\n火のそばに座って、くつろいでくれ。順を追って説明しよう。", "野外で生き抜くのに必要な技術を身につけることは非常に大切です。十分に休息を取り、しっかり準備を整えた冒険者は、この生き方を生き抜ける見込みがずっと高いのです。", "さて、基本は身につけたから、次は近くの村のトレーナーたちから専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしいキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0xeb724be6, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96102] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、OrgrimmarのSnangと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, nil, 0xde7f398c, 0xb3ef6f61, 0x49663bd1, nil, nil, "...mm" },
  [96103] = { "ハゲワシのご馳走", "Gnawed SkullをRog'marにいるNeza Bloodsnoutのところへ持って行く。", "骸骨はひどく損なわれている。手足に残る深い傷跡は、牙や爪の跡とおぼろげに一致する。照りつける日差しの下で幾日も過ごしたせいで、骨は白く脆くなってもいる。襲った者の残忍さと天候の厳しさのために、犠牲者が誰なのかは謎となっている。\n\n骸骨を丸ごと持っていくことはできないが、頭蓋骨をRog'marのハンターのもとへ持っていけば、何か分かるかもしれない。", nil, nil, 0x3042c70f, 0xdf9a1667, 0x18ee6f7e, nil, nil, "...mm" },
  [96104] = { "Striderの歌", "Intact Tallstrider BeakをRog'marにいるNeza Bloodsnoutのところへ持って行く。", "この傷跡はライオンのものだ。見たところ、こいつは特に大きい。近くの群れの長だろう。\n\n本当なら喜んで自分でその獣を狩りたいところだが、先に権利があるのはお前だ。代わりに手を貸そう。\n\n傷ついたtallstriderの鳴き声をまねる笛を作ってやれる。それを使えばライオンをおびき出せる。正しい音を出すには、tallstriderのくちばしが一つあればいい。\n\ntallstriderなら平原のあちこちにいる。くちばしを見つけてきてくれれば、狩りを始められるぞ！", nil, nil, 0x37a5cbb4, 0x893a6968, 0x5de39716, nil, nil, "...mm" },
  [96105] = { "野生の平原の王", "Tallstrider Callを使ってライオンの群れの長を呼び出す。その獣を倒し、Rog'marにいるNeza Bloodsnoutのためにその皮を取ってくる。", "笛ができたぞ、{name}。\n\nそれを持って、ライオンが棲む南の丘の頂上へ行け。\n\n獲物と向き合う覚悟ができたら笛を吹け。獣が現れるはずだ。\n\n狩りの幸運を祈る。栄光とともに戻ってくるがいい。", nil, nil, 0xc62bac87, 0x3ab4cdf5, 0x6fee627e, nil, nil, "...mm" },
  [96107] = { "矢羽根用の羽根", "Plains Buzzard Featherを$N1枚、Rog'marにいるNeza Bloodsnoutのところへ持って行く。", "ハンターが一生のうちに使い果たす矢は、空の星の数よりも多いのよ。\n\n私は自分の矢を手作りしているの。自分の仕事しか信用しないから。\n\n近くにいるハゲワシの硬い羽根は、矢羽根にうってつけなの。いくつか集めて、手を貸してもらえないかしら？", nil, nil, 0x0c7d04b3, 0xbed7ffa3, 0x61c3d52b, nil, nil, "...mm" },
  [96108] = { "毒の矢じり", "Glade Viper Venomのサンプルを4個、Rog'marにいるNeza Bloodsnoutのところへ持って行く。", "矢はいつだって欠かせないけれど、獲物を仕留めるにはもっと強力なものが必要なときもあるわ。\n\nそこで役に立つのが毒の塗り薬よ。肉は台無しになるけど、とにかく仕留めたいなら役目は果たしてくれるわ。\n\n毒は煎じて作ることもできるし、勇気があるなら採ってくることもできる。あなたは後者に見えるわね。\n\n南の池のそばにいる毒蛇は、強力な毒を出すの。私の見立てが正しければ、あなたならそれを少し集められると思うわ。", nil, nil, 0xeb84f778, 0xd6ba3ab9, 0x61324629, nil, nil, "...mm" },
  [96109] = { "ハンターの矢筒", "Rog'marにいるNeza Bloodsnoutのために、Prized Lion Hideを6枚集める。", "ハンターにとって、武器と同じくらい大切なのが矢筒よ。良い矢筒はたくさんの矢が入るのに、身に着ける者の動きを鈍らせるほど大きくはないの。丈夫で、体にぴったり合わなければならないわ。\n\nこのあたりでは、矢筒の材料としてライオンの毛皮に勝るものはないわ。平原で生きるハンターの暮らしに、もともとよく合っているの。\n\nライオンは南の丘に集まっているわ。ここからも見えるでしょう。どうか、その毛皮を持ってきてちょうだい。", nil, nil, 0x800fa039, 0x11152be0, 0xbfa6c331, nil, nil, "...mm" },
  [96125] = { "救援を求めて", "Bolder'okのogreたちの中のどこかにいるDunston Willisを見つける。", "ライオンの皮も集まったし、オークの密猟者どもも片付いたから、ようやく一息つける。\n\n少なくとも、そう言いたいところなんだが、見張りを交代してくれるはずの男が行方不明でな。\n\n凄腕の探検家Dunston Willisが、数日前に北のogreの集落を調べに行った。戻ったら私の持ち場を引き継ぐと言っていたんだ。\n\n彼を見つけてくれ。生きていたら、ここへ連れて帰ってきてくれ。もし肉を吊るすフックに吊るされていたら、証拠を持ってきてくれ。そうすればDemarが別の誰かをよこしてくれる。", nil, nil, 0x95a013a5, 0x8efb13cb, 0xf7e0d354, nil, nil, "...mm" },
  [96126] = { "Ogreの捕虜", "Gronok the Butcherを見つけて倒し、Dunstonの枷の鍵を彼に届ける。", "どうやってここへ入ってきたのか分からないが、頼む、話を聞いてくれ。\n\n知っての通り、私はFarholde Keepの見張りを務めている。\n\n巡回中にこの獣どもの一団に待ち伏せされて、捕虜になった。今では奴らの見世物として、闘技場で戦わされている。\n\nもうあまり力が残っていない。逃げるなら、今しかない。\n\n私を捕らえているのは、「Gronok the Butcher」と呼ばれているogreだ。そいつが私の枷の鍵を持っている。その鍵を持ってきて、ここから出るのを手伝ってくれないか？", nil, nil, 0xa55362d4, 0x09aa0a47, 0x0a8f855f, nil, nil, "...mm" },
  [96130] = { "Chakuyak", "Chakuyakを倒し、その毛皮を持ち帰ってください。", "近くの丘で狩りをするプレーリーウルフの中に、特に攻撃的な一頭がいます。私たちはそれをChakuyakと呼ぶようになりました。遠くからやって来る旅人にとって脅威となっているのです。\n\n彼女はStonebull Lakeの西の木立を、茂みから茂みへと移りながら獲物をつけ狙っています。\n\nこの脅威を終わらせてその毛皮を持ってきてくれれば、族長にあなたの功をたたえて伝えましょう。気をつけて、彼女は危険です！ そこで彼女を狙う他のハンターたちに出会うかもしれません。力を合わせられるかもしれませんね。", "大きな狼は見つかったか？", "これほど美しい生き物の命を奪うのは悲しいことですが、私たちの民の安全のためには必要でした。毛皮は決して無駄にしないとお約束します。ありがとうございます。", 0x5e7713ac, 0x243d382f, 0x76d59655, 0xf8c970d1, 0x599fc946, "....." },
  [96131] = { "Oldstoneだが古き友", "Faintly Glowing BranchをKetharasのもとへ持っていく。", "ここの南の洞窟に住んでる、あの頑固な年寄りにはもう会ったよね？\n\nこの杖を、私の羽根と一緒に彼のところへ持っていって。意味が分かるはずだよ。分からないかもしれないけど！どっちにしても、彼の注意は引けるさ。\n\n石頭の年寄りかもしれないけど、頼りになる。こんな重大な件を任せられる、数少ない定命の者のひとりなんだ。\n\n急いで、Dirtwalker！Hyjalに私たちには見えない影が落ちかかっている気がするんだ。", nil, nil, 0xef74a90f, 0xf0b626d8, 0x994fd83e, nil, nil, "...mm" },
  [96135] = { "我が呼び声に耳を傾けて", "Twisted Totemsを使い、quilboarの儀式を終わらせる。", "うえっ、このいまいましいトーテムのそばにいるだけで寒気がするわい。だが、それでいい。これだけねじれた穢れがあれば、まさにquilboarのエレメンタルを呼び出すのに必要なものだ。\n\nThousand Needlesへ行って、防衛線を張るのにふさわしい場所を見つけてくれ。蒸気の泉がいいだろう。あそこは火、土、水、風がどれも豊富だ。このトーテムを置いて、戦いに備えろ。Razormaneはお前さんの邪魔を快くは思わんだろうからな。", nil, nil, 0xb87aaede, 0x5eafbe6d, 0x93cfea2b, nil, nil, "...mm" },
  [96136] = { "大気の呼び声", "Thousand NeedlesでPrate Cloudseerを見つける。", "あなた自身もきっと経験したとおり、Azerothの元素はZephrasのものとは異なります。精霊界の中で自然の力を導くことと、この地上の泥の中でそれを行うことは、まったく別のことなのです。\n\nあなたに風のトーテムを授けることもできますが、地に縛られた他の見習いたちを鍛えている者に会うほうが、あなたのためになると思います。いかがですか、{name}？", nil, nil, 0x8f4acf86, 0x7a57cbe0, 0x94a7ee28, nil, nil, "...mm" },
  [96137] = { "Ira's Dagger", "Young Black Ravagerを$N1体とBlack Ravagerを$N2体倒し、詳しい情報を聞きにDarkshireのSirra Von'Indiのところへ戻る。", "森の獣が旅人を襲わぬよう守り、森の安全を保っていた自称レンジャー、Iraの小さな短剣。\n\nIraの霊が今も森をさまよっているのなら、彼女のやり残したことは、森の至るところで犠牲者を出し続けているworgを一掃することなのかもしれない。", nil, nil, 0x26c52f95, 0x8b815c85, 0x2af9a1e7, nil, nil, "...mm" },
  [96138] = { "Merrick's Bow", "Splinter Fist Warriorを$N1体とSplinter Fist Taskmasterを$N2体倒し、詳しい情報を聞くためにDarkshireのSirra Von'Indiのところへ戻ってください。", "迫りくる敵から街道を守ることを誇りとした名高いWatcher、Merrick Valorの霊が残した弓。\n\nMerrickの霊が今も街道をさまよっているのなら、彼のやり残したことは、Raven Hillにある故郷の近くの侵入者を一掃することなのかもしれない。町の南にいるogreたちが、彼の霊を悩ませているものかもしれない。", nil, nil, 0xfe4f08e4, 0xea183417, 0xd5097423, nil, nil, "...mm" },
  [96139] = { "Valor家", "Raven Hillで何か手掛かりになるものを探し、DarkshireのSirra Von'Indiのところへ戻ってください。", "このような暗い時代には、敵と同じくらい英雄たちのことを覚えておくことが大切だ。善きLady Altheaのような人々や、Raven Hillで命を落とした者たちの勇敢さがなければ、Darkshireは今も立ってはいなかっただろう。\n\nRaven Hillについてはよく読んだことがあるか？いや、もちろんないだろう。その歴史は人々と共に消し去られてしまった。私の書庫は見事なものだが、その話題についてはほとんど何もない。\n\nもし何か見つけたら、ここへ持ってきてもらえるとありがたい。あの人々は覚えられているべきなのだ。", "何か見つかったか？あまり期待はしていないがな。", "この本はValor家についてのもののようだ。何人かは聞いたことがある気がする。善良な人たちだ。とはいえ、まるまる一冊の本にするほどの人たちかどうかは分からないな。\n\nこの本の写しを作ってやろう。旅の途中で彼らに関係するものを見つけたら、喜んで引き取るよ。", 0x27a57039, 0x2c2db2c8, 0xb8e94707, 0xd0323cfc, 0xba858917, "....." },
  [96145] = { "翼と爪を越えて", "Shrine of AvianaでPhoebe Highfeatherを探す。", "旅の方、気をつけて！この先にShrine of Avianaがありますが、今そのあたりはWormwing族のharpiesに支配されています。\n\n私の一族、Highfeathersと同じく、私もAvianaに仕える者ですが、Wormwingsはそれほど忠実ではありません。縄張りを通る者には誰であれ危険な存在です。\n\n彼らをうまく通り抜けられたら、私のいとこのPhoebe Highfeatherが祠を守る手助けをしています。", nil, nil, 0xedc8630e, 0x74a5d024, 0x040c78d4, nil, nil, "...mm" },
  [96204] = { "Windshaperの怒り", "Lumina Windsingerに同行し、彼女がFenris Keepから脱出するのを手助けしてください。", "自由になった今、あの卑しい生き物どもに、Windshaperに目をつけたことを後悔させてやる。\n\nここを出よう、{class}。", nil, "改めてありがとう、{name}。ここにいるTrevanと知り合いになっていたところです。あなたを私の後を追わせたのは彼だと聞きました。\n\nこれまでの旅で、パラディンについては……あまり好意的とは言えない話を耳にしてきました。Hordeの領土を旅する、空に触れたshen'doreiのエルフとして、不寛容や偏見がいかにたやすく根を張るか、私にはよく分かります。\n\nあなたとあなたの同胞には、Windshapersの中に友がいますよ。", 0x537b0fef, 0xdc69980b, 0x0c4dedf9, nil, 0x893e3e79, "...m." },
  [96209] = { "Ancient、Orokai", "MoongladeでOrokaiを探し出す。", "古代の者、Orokaiが町のすぐ外で見張りに立っています。これを彼のところへ持っていってください。古代の者たちは驚くほど賢いのです。この枝が親木から長く離れすぎていなければ、彼は枝と「話し」て、枝が語る物語を知ることができるでしょう。\n\nOrokaiは町の南西、そう遠くないところにいます。", nil, nil, 0x91a08c73, 0x2a64e9a6, 0xbbf33ee7, nil, nil, "...mm" },
  [96222] = { "Khan Hratha", "Maraudine Key FragmentをDesolaceのUmarakに届ける。", "この地域全体で戦争が荒れ狂う中、Maraudineのcentaurは誰にも挑まれることなくValley of Spearsに居座っている。他の氏族が奴らの存在に見て見ぬふりを続ければ、やがて奴らは冷酷になり、さらなる動乱を引き起こすのではないかと心配だ。\n\nKhan HrathaはMaraudine Key Fragmentを持っている。私はそれを交渉の材料として手に入れたい。そこのcentaurから戦の角笛の吹き口を見つけ、それを使って最も高い山頂で奴に挑め。\n\n鍵を持ってきてくれれば、お前に話がある。", nil, nil, 0xa9d55f09, 0xffb7769a, 0x95b5e8c9, nil, nil, "...mm" },
  [96241] = { "毒の話をしようぜ、なあ", "Toxin Extractorを使って、GloomriseのGnawed CorpsesからGloomrise Toxin Sampleを$N1個集めて下さい。", "Gloomriseの方で、何か妙なことが起きてるんだ。このMazu'kon様の耳にも、あのあたりを這い回ってる新しい嫌な獣どもの話がたっぷり入ってくる。\n\nあの気味の悪い虫どもの毒には特別な性質があるって言う奴もいて、それがオレの好奇心をくすぐるのさ。オレの抽出器を持っていけ。あそこに転がってる死体にそいつを使って、毒を採ってくるんだ。やってくれたら、オレはお前に借りができる、なあ。", nil, nil, 0xb964176e, 0x8fd016de, 0x40a8707c, nil, nil, "...mm" },
  [96243] = { "大地の呼び声", "Dun MoroghでTeo Hammerstormを見つけてください。", "とっくに大地の声に耳を傾けるべき時だぞ、勇敢なシャーマンよ。精霊はすでにお前さんの肌をちくちくと刺しておるが、ひとたび岩と語れば、大地そのものがお前さんの足の下で……そして魂の中で、しっかりと固まるだろう。\n\nColdridge ValleyにいるTeo Hammerstormを訪ねよ。槌と火と意志で鍛え上げられた砦、Anvilmarの中におる。", nil, nil, 0xe316c17f, 0xf8e81384, 0x13c0eb8d, nil, nil, "...mm" },
  [96246] = { "Blackmaw Pouches", nil, nil, nil, nil, 0xe558c49d, nil, nil, nil, nil, ".mmmm" },
  [96252] = { "色あせた財宝", "Wormwing Harpyの巣からTarnished Highfeather Banglesを$N1個集める。", "{class}、あなたにお願いがあります。とても個人的なことなのですが。\n\nWormwingsが待ち伏せして私の姉妹たちを殺したとき、奴らは姉妹たちの装身具を戦いの戦利品だと言って奪っていきました。さらにひどいことに、その宝を、まだ生まれていない雛と一緒に巣に隠しているのです。奴らの堕落をさらに示すものです。\n\nどうか倒れた姉妹たちの宝を集めてください。できれば孵っていない卵を傷つけないでほしいのですが、敵の割れた卵のことで眠れなくなるつもりはありません。", nil, nil, 0x45dbdc27, 0x0b7a4293, 0xc6413990, nil, nil, "...mm" },
  [96255] = { "混ざり合った骨髄", "Awakened Fel Ash Slimeを倒す。", "<骨の山の中で何かが不気味にうごめき、新しく加えられた骨の下から緑色の粘液がにじみ出てくる。>", nil, nil, 0xa84078ba, 0xe1a19978, 0xe70d9892, nil, nil, "...mm" },
  [96259] = { "死者を守る", "Gloomrise Hatchlingを$N1体とGloomrise Soldierを$N2体倒して下さい。", "このキャンプのすぐ北西、Gloomriseと呼ばれる場所に、古いトーレンの埋葬地があります。近頃、そこに特に凶暴なクモの群れが巣くっています。このクモたちはMulgoreの民にとって脅威であるだけでなく、多くのトーレンが神聖とみなす場所を傷つけてもいるのです。\n\nGloomriseへ行き、この蔓延を終わらせてくれれば、大きな助けになります。それを成し遂げれば、祖霊もきっとあなたに微笑むでしょう。", nil, nil, 0x554fb829, 0xfedbb124, 0x55e7bece, nil, nil, "...mm" },
  [96260] = { "鋼より強い", "Gloomrise SpinnerからCrystalline Silkを$N1本集めて下さい。", "Gloomriseの埋葬地に何が起きたか聞いたかい？ 巨大なクモどもが、死者を目覚めさせるほど強い毒を持つという噂だが、そいつらが野火のように広がっているんだ。まったく嫌な話だよ。\n\n調査に送り出された斥候の一人が、半死半生で戻ってきた。信じられないほど丈夫な、水晶のようなクモの糸にまみれてな。取れるだけは採取したが、さらに研究するために、この糸のサンプルがもっと欲しいんだ。\n\nこのcrystalline silkをもっと持ってきてくれたら、報酬を出そう。", nil, nil, 0x9eb7d49a, 0x87e2b5d5, 0x7ddec3da, nil, nil, "...mm" },
  [96261] = { "母グモ", "GloomriseでBroodmother Valraxxを倒して下さい。", "Gloomriseで直面しているような蔓延では、よくあることだが、一匹の強力な女王が敵対的なクモの急速な繁殖を招くことが多い。\n\nこの獣どもを永久に追い払いたいなら、その始祖を探し出して始末しなければならない。Gloomriseへ行ったら、そこの母グモを見つけて倒してくれ。仲間を連れて、何が起きても対応できるようにしておくことを勧める。これはただのクモではないようだ。", nil, nil, 0xcdf04d8e, 0x37e65943, 0x0eed8922, nil, nil, "...mm" },
  [96262] = { "Prickly Pinecones", "健康な木の下でPrickly Pineconesを$N1個集める。", "雛のころからこの丘を知ってるんだ。ひとつ知ってることがあるとすれば、松ぼっくりはたくさんの問題を解決できるってことさ。\n\nたぶん思ってたのと違っただろ、ね？\n\n<カラスは共犯者めいた様子であなたにウインクする。>\n\nいくつか取ってきてよ。私が企んでるちょっとした計画の一部なんだ。骨折り甲斐はあるって約束するよ。\n\n近くの健康な木や生きてる木の下ならどれでも見つかるはずさ。でも汚染された木には近づかないで。あの松ぼっくりは全然使えないからね！", nil, nil, 0xae528202, 0xeef22f1d, 0x1af91b33, nil, nil, "...mm" },
  [96264] = { "精霊の助け", "Razorfen KraulでCharlga Razorflankを倒し、quilboarの計画に関する情報を集めて下さい。", "それで、お前さんは今や大物のシャーマンってわけか？ エレメントを極めて、それを役立てたいと？ ちょうどいい話があるぞ。\n\nエレメントの敬意が欲しけりゃ、奴らへの借りを返さなきゃならん。奴らはお前を助け、お前は奴らを助ける。そして今、奴らは自分たちの力を悪用しようとする連中に対抗するため、得られる限りの助けを必要としてるんだ。\n\n大地が唸ってるぞ、{name}。quilboarどもが恐ろしい力の儀式のために集まっていると告げている。奴らのkraulを調べに行って、何を企んでいるのか確かめねばならん。見つけたものは何でも持ち帰ってくれ。", nil, nil, 0x3a904965, 0xd3648ee8, 0x7dfb9fdc, nil, nil, "...mm" },
  [96265] = { "Barrow Deepsの秘密", "Corrupted GemstoneをWinterspringのThera Duskwhisperのもとへ持っていく。", "<汚染されたかけらが合わさり、汚れた力が渦巻く宝石になった。Watchersはこれを見たがるだろう。>", nil, nil, 0xe4926094, 0x968417d5, 0x0c2746a5, nil, nil, "...mm" },
  [96294] = { "さらに暗い真実", "Broodmother Valraxxから回収した手紙を、Skywatcher PlateauのMuln Earthfuryのところへ持って行って下さい。", "<あなたが今倒した母グモは、クモなどではなく、歪んだ獣の姿をとったナイトエルフのドルイドだった。Gloomriseのクモたちの正体と目的について、さまざまな疑問が頭にあふれる。\n\n死んだエルフのローブのひだから、一枚の書き付けがのぞいているのに気づく。この文書が、頭を満たす疑問のいくつかに答えてくれるかもしれない。>", nil, nil, 0xceb16734, 0xff9e4493, 0x8d307e49, nil, nil, "...mm" },
  [96296] = { "悪臭を放つ汚染", "近くの木からCorrupted Knotsを$N1個見つけて取り除く。", "<脈打つこぶに近づいた途端、それは木から落ち、緑色の樹液が滴っているのがあらわになる。この木は樹皮の中に深く広がった汚染を抱えているようだが、まだ死んではいない。\n\n見回すと、周りの木々の一部にも広がっているのは明らかだが、どれも同じ程度に汚染に苦しんでいるわけではない。\n\n近くの病んだ木々を救うのに、まだ遅すぎはしないかもしれない。\n\n見つけられる限りの汚染されたこぶを取り除けば、Highfeathersもきっと感謝するだろう。>", nil, nil, 0x15581946, 0x33d2f8f5, 0xec9247aa, nil, nil, "...mm" },
  [96301] = { "強力洗浄", "Well of Eternityに入り、それがVenom-dripping Heartに及ぼす影響を観察する。", "キメラGhansurokの毒々しい、毒を持つ心臓を手に、Well of Eternityの古の水に浸しなさい。\n\n水が汚染にどう反応するか、組織的な汚染が無に帰そうとしたものを自然がいかに覚えているかを、よく見ていなさい。\n\nその臓器を私のもとへ持ち帰りなさい。共にそれが示す兆しを読み解き、均衡をまだ取り戻せるのか……それとも傷が深すぎるのかを知りましょう。", nil, nil, 0x1a1675e0, 0xe2ca219e, 0xdce1a970, nil, nil, "...mm" },
  [96302] = { "大いなる赦し", "Marnの香を持っていき、その煙でArchimondeの遺骸の周りの空気を清める。", "この強く、刺激の強い樹脂を固めておきました。この調合したお香を持って、The Defilerの亡骸の前に立ちなさい。\n\n煙が立ちのぼったら呪文を唱えなさい。残るものを追い払うためではなく、霊を鎮めるために。その姿は今も恐怖の記憶をまとい、長く留まる者の心に今なお恐れをかき立てるのです。\n\n煙に静けさと決意を運ばせ、心を恐怖から守りなさい。ここを歩む者たちが、恐怖ではなく勝利を思い出せるように。", nil, nil, 0x0b0d69f2, 0x49ecfbef, 0xc6e43f87, nil, nil, "...mm" },
  [96303] = { "記憶の霧", "Enchanted Branchを使って、Nordrassilの周りでウィスプを$N1体解き放つ。", "{name}、大いなる戦いの間にHyjalへ呼ばれた祖先の霊は、すべてが失われたわけではありません。大いなる犠牲のあと、Nordrassilに引き寄せられて、今も留まっているものもいます。このウィスプたちは泉の上に垂れ下がる根の天蓋の中に留まり、この世とあの世の狭間の煉獄に囚われています。\n\nこのenchanted branchを使ってウィスプたちに安らぎをもたらし、その記憶を永遠と結びつけてあげてください。\n\nすべてをあなた自身で解き放つ必要はありません。5体の意志を取り戻し、枝を私たちのもとへ返してください。", nil, nil, 0xe89ceca4, 0xb260d358, 0x895d05d4, nil, nil, "...mm" },
  [96321] = { "死にゆく神", "Mount Hyjalで、Faintly Glowing Staffに興味を持ちそうな人を見つける。", "もう……あまり時間がない、定命の者よ。この杖を持っていけ。世界樹の枝だ……汚染され……歪んでいる。私がここまで運んできたのだ……\n\nWild Godsに……知らせねば。彼女のもとへ持っていけ。あの……カラスのもとへ……\n\n<死にゆくWild Godは動かなくなり、その目はうつろに前を見つめている。わずかに残った実体のある姿も崩れ、散っていくようだ。地面には微かに光る枝があり、その先端には病んだ緑色の結晶がはめ込まれている。>", nil, nil, 0x0fa378ff, 0x64106ec2, 0x3450f223, nil, nil, "...mm" },
  [96322] = { "今や苦い復讐", "Felflickと話す。", "なあ、定命の者にしちゃ、お前が命令にあっさり従うのには感心するぜ。\n\nあそこへ行って、眉ひとつ動かさずにあいつらを皆殺しにしてきたんだからな！\n\nあぁぁ……だが今度はお前が約束を果たす番だ、「お友達」。間抜けなAshen Reignを解体し、指導者どもを始末して、ここでの作戦を潰す手伝いをしてやったんだ。\n\n俺は自由を手に入れるだけのことはしたと思うぜ。\n\n<Felflickの目が期待にきらめく。>", nil, nil, 0x1a3bcf28, 0xbff845e3, 0x1e95b85a, nil, nil, "...mm" },
  [96332] = { "ささやかな仕返し", "Alcaz Prisonに入ってStrashasz Soldiersを$N1体とStrashaz Enchantressesを$N2体倒し、Tidemistress Ca'zassの首をSergeant Ulkaのもとへ持っていく。", "我々が退却していたとき、Nagaの第二波が砦に迫っていた。戦いはまだ中で続いているはずだ。\n\n我らKor'kronは血には血で応じる。どうせあそこへ入るなら、目にしたNagaは皆殺せ。奴らの中に女魔術師もいた。あれが指導者に違いない。その女の首を持ってこい。\n\n今日、我々は多くの優れたオークを失った。受けた分を返さなかったと知りながら、安らかに眠るつもりはない。", nil, nil, 0x1a1e0f10, 0x2a538404, 0x9957f7af, nil, nil, "...mm" },
  [96334] = { "Blood Red Bandanas", "Alcaz Prisonに入り、そこにいる人間の衛兵からBlood Red Bandanasを$N1個集める。", "我々が戦った人間のほとんどは、blood red bandanaを着けていた。Eastern Kingdomsで活動している、赤い覆面で知られる「The Defias Brotherhood」という犯罪組織の話を聞いた覚えがある。なぜ奴らがここKalimdorで活動しているのかは分からんが、行く手を阻む者は殺し、その覆面をOrgrimmarのEitriggのもとへ届けてくれ。\n\n彼なら、これが本当にDefiasの覆面かどうか見分けられるだろう。", nil, nil, 0xc5237fd4, 0x5ef8533e, 0x207c5ebf, nil, nil, "...mm" },
  [96335] = { "鉄の鎖の男", "Alcaz PrisonのThe QuestionerからAlcaz Shackle Keyを取り戻す。", "すごい！今のは見事だった。あのドラゴンの倒し方ときたら、本当に大したものだよ！\n\nせっかくここにいるんだし……この鉄球と鎖から抜け出すのを手伝ってもらえないかな？\n\nもう逃げたり殺されたりしていなければ、「The Questioner」と呼ばれている拷問係がこの枷の鍵を持っているはずだ。あのサディストから鍵を奪って、私のところへ持ってきてくれ。\n\nそうしてくれたら、十分な見返りがあると約束するよ。", nil, nil, 0x13152ee6, 0xff532844, 0xe7e955b8, nil, nil, "...mm" },
  [96337] = { "黄金より価値あるもの", "Mason Conneryから渡されたメモを使って、彼の隠し財宝を見つける。", "私を解放してくれたら見返りはあると言っただろう。君にやる金はないが、もっといいものがある。\n\nこれを持っていってくれ。金よりも価値のある宝を見つける助けになる。好きにしていいが、もし誰かにどこで手に入れたかと聞かれたら、くれた奴は死んだと言ってくれ。\n\nドラゴンの炎で蒸発した……海に吹き飛ばされたとな。", nil, nil, 0xe7c0a763, 0xaf347d6f, 0x50921a6d, nil, nil, "...mm" },
  [96339] = { "レガシー報酬：Replica Ironforge Air Rifle", nil, nil, nil, nil, 0x049ac689, nil, nil, nil, nil, ".mmmm" },
  [96369] = { "Folkarへの悪い知らせ", "Commander Folkarのもとへ報告に戻る。", "<王は死んだ。Nagaが攻めてくる直前、脱走を試みて殺されたのだ。この知らせを得るために多くのKor'kronが死んだが、この情報はAllianceを根底から揺るがしかねない。Commander Folkarのもとへ戻り、知ったことをできるだけ早く伝えなければならない。>", nil, nil, 0x41f46ebc, 0xb6344476, 0x5e6514d9, nil, nil, "...mm" },
  [96376] = { "国家機密", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96377] = { "国家機密", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96379] = { "国家機密", nil, nil, nil, nil, 0x7294e55b, nil, nil, nil, nil, ".mmmm" },
  [96381] = { "ちょっとした汚れ仕事", "Alcaz Prisonに入ってStrashasz Soldiersを$N1体とStrashaz Enchantressesを$N2体倒し、Tidemistress Ca'zassの首をSully McClearyのもとへ持っていく。", "君がLady Proudmooreの話を盗み聞きしに行っとる間、わしは頼りの望遠鏡でAlcazの岸を見張っとったんじゃ。どうやら島が攻撃を受けとるらしい。nagaを見たぞ。大勢が岸に押し寄せとった。\n\nnagaに関しちゃ、敵の敵は決して味方じゃない。だから世のためにいくらか片付けてやろう。それに、頭目らしいのも見つけた。命令をがなり立てとる呪文使いの女じゃ。できれば、そいつも始末してくれ。", nil, nil, 0xc062c89e, 0x3abd7349, 0x28a62023, nil, nil, "...mm" },
  [96383] = { "レガシー報酬：Spectral Bear Cub", nil, nil, nil, nil, 0x282c1e94, nil, nil, nil, nil, ".mmmm" },
  [96390] = { "芽のうちに摘め", "Dun MoroghでDark Iron Spiesを$N1人倒してください。", "Dark Ironの密偵どもがDun Moroghに入り込んどる。何が目的かは分からんが、これは大きくなる前に芽のうちに摘んでおかにゃならん問題だ。\n\n東のIronband's Compoundへ向かい、そこで見つけたDark Ironの密偵どもを始末してこい。", "どうだった？やつらをこっぴどく懲らしめてやったか？", "このDark Ironどもは親戚かもしれんが、家族じゃねえ、それは確かだ。あの呪われた山から迷い出てきた奴らにどんな災難が降りかかろうと、涙なんぞ一滴も流さんよ。\n\nこれで奴らがこの地へのさらなる侵入を思いとどまってくれりゃいいんだがな。", 0x5f38218b, 0x10fb22fa, 0x9db0e0ef, 0x68b3128a, 0xd5731f3e, "....." },
  [96391] = { "地下の地図", "Dark Iron MapをDun MoroghのEarthseer Farsenに届けてください。", "手にしている地図には、地下トンネルと街道が複雑に連なり、そのすべてがIronforgeそのものの真下の一点に集まっているように描かれているようだ。\r\n\nルーンはDark Ironドワーフの醜く角ばったルーン文字で書かれているため、何と書いてあるのかは確かではないが、これらのトンネルの目的は推測できる。地図を読んでいると、一陣の風が吹き抜け、それに乗ってドワーフの声がかすかに聞こえてくる。これはEarthseer Farsenに見てもらう必要がある。", "おや、これは何だい？", "この地図を見る限り、このDark Ironどもは確かにIronforgeの地下の金庫室への侵入を企んでいるようだ。お前さんが東で叩きのめした一団は偵察部隊に違いない。\n\nこれを持ってきてくれて感謝するぞ。急げば、奴らが下で何を狙っているにせよ、先手を打てるかもしれん。", 0x9d9cce92, 0x0559f95b, 0x9898e535, 0x52844eeb, 0x1c2fe859, "....." },
  [96392] = { "Farsenの見張り", "Earthseer Farsenと話し、Dark Ironの脅威を見届けるため、彼の遠見の力を貸してくれるよう頼む。", "ようこそ、友よ。わしの名はEarthseer Farsen。Aerie PeakからDun Moroghに来ておる。旅の途中で、どうにも気づいてしまってな。その……ちょっとしたDark Iron Dwarfの問題があるようなのだ。\n\n少し時間があるなら、どういうことか見せてやろう。うまくいきそうな魔法をちょっと持っておるのでな。", "遠見は実に多くのものを見せてくれる。見たくないものまでな。", "これで分かったか、{class}？ ゴキブリみてえにうじゃうじゃいやがる。しかもそいつは空から見える分だけだ。\n\nお前さん、なかなか頑丈そうだな。ちょいと暴れてみる気はねえか？", 0x9243cd15, 0x987a4089, 0xce20450c, 0x19a9ef2c, 0x478676d1, "....." },
  [96393] = { "Old Ironforgeへの侵攻", "Old Ironforgeの地下にあるHall of Thanesへ入り、Head of Durgen Dirgehammerを手に入れてください。", "仲間を集めて、Old Ironforgeの下の洞窟へ降りていけ。そこのHall of Thanesに入り、下層の地下室まで押し進むのだ。\n\nわしのDark Iron語は少々錆びついておるが、ひとつの名前は読み取れる。Durgen Dirgehammerという者だ。おそらくそいつが指揮官だろう。そいつの首を取り、King Magni Bronzebeardに届けよ。\n\nああ、それと届ける時には、旧友のFarsenがよろしく言っておったと伝えてくれ！", "何の用だ、市民よ？", "Dark Ironの侵入だと――わしらの足元でか？ まあ、Dark Ironの司令官が片付けられたと聞いて安心したわい。\n\n衛兵たちが乗り込んで残りの雑兵を片付ける。裂け目は塞ぎ、下層は補強して、二度と侵入できないようにしておこう。\n\nIronforgeへの尽力に感謝するぞ、{class}。ささやかだが感謝のしるしだ、受け取ってくれ。ああ、それと、あの年寄りのWildhammerの岩抱き野郎Farsenにまた会ったら、ちゃんと顔を見せに来いと伝えてくれ。", 0x48866402, 0xe0bec594, 0xa08604c5, 0xa75dc075, 0x0fc00f59, "....." },
  [96394] = { "安らがぬ死者", "Enraged Apparitionを$N1体とTormented Soulを$N2体倒し、Anvilmarの霊を眠らせてください。", "何かがHall of Thanesの墓を乱したようで、地下室の奥深くから妙な物音が聞こえてくるそうだ。死者の霊は眠りが浅い。下で何が起きているにせよ、それが彼らを驚かせてしまったらしい。\n\n下へ降りて、何とかしてきてくれ。死者が目を覚ましておったら……また眠らせてやれ！", "グールや幽霊に構っている暇はない。私にはこの下でやるべき仕事があるのだ。", "ああ、よかった、片付いたんだな。他の番人たちが「幽霊」だの「怒れる死者」だのを理由に広間に入って仕事をするのを拒んでいたんじゃ困るだろう？", 0x69066003, 0x6a43847e, 0xd9e1bd9c, 0x225e19e2, 0x1d4545a7, "....." },
  [96395] = { "古き遺恨", "Faldrim Anvilmarの霊を眠らせ、Hall of ThanesのGhostly Attendantのところへ戻る。", "わが……Thane……偉大なる……Thaneが……休まねば……ならぬ……\n\nどうか……彼を……助けて……休ませて……\n\n古の……恨みに……呑まれ……休めぬ……", "<幽霊のような姿は、うつろな目であなたの向こうを見つめている。口は動いているが、聞き取れないかすれた低い音しか聞こえない。>", "わが……領主……は……眠る……そう……眠る。\n\nありがとう……\n\nわしも……眠る……", 0x372fadb2, 0xf47ad935, 0x22f3d060, 0x9e32e5af, 0x80ede96a, "....." },
  [96403] = { "大切な家宝", "Hall of ThanesでDwarven Heirloomを$N1個集めてください。", "そこのあんた、冒険者……ぜひ手を貸してほしいんだ。\n\n地下室をこっそり――じゃなくて……「巡回」していたら、Dark Ironのドワーフの一団が掘削機に乗って深みから現れたんだよ！ 何のために来たのかはわからないが、あそこには値のつけられないお宝――じゃなくて、その……「大切な文化的遺産」があるんだ！ そういう遺物を見つけたら、取り戻してここへ持ってきてくれ。\n\n取り戻したものはすべて目録に記され、しかるべき名誉ある場所に戻されると約束するよ。", "<Thomはあなたを見ながら、うわの空で両手をこすり合わせているようだ。>", "見てごらん、度胸があるうえに商才まであるなんて！ 僕は約束を守るノームだ、報酬はしっかり稼いだものだよ！\n\nさあ、戦利品を見せて――あ、いや、その……取り戻した家宝をね。すぐに鑑定――失礼、「目録作り」を始めないと。できるだけ早く元の場所に戻せるようにね。", 0xdb5e0561, 0x7bf6ecf5, 0x1019355e, 0xb065081e, 0xd63d4304, "....." },
  [96408] = { "Dun Moroghへの訪問者", "Gol'Bolar Quarryを見下ろす野営地を調べてください。", "昨夜、うちの山岳兵のひとりが、東の丘の斜面に焚き火を見つけた。かなり高いところで、Gol'Bolar Quarryを見下ろす場所らしい。\n\nたぶん何でもないだろうが、その野営地を確かめてきてほしい。友好的なら、何も問題はない。友好的でなければ……まあ、どうすればいいかはわかるな。", nil, "やあ、友よ。元気かい？", 0x7b3a9976, 0x89d2ded4, 0x1a6a0853, nil, 0x9c8725d7, "...m." },
  [96435] = { "ふさわしい最期", "ウォーロックの骨を、スライムの池の近くにある骨の山に投げ込む。", "<FelflickはAshen Reignの指導者たちの血まみれの骨を眺めながら、うれしそうに高笑いする。>\n\nおお、こいつは最高だ！\n\n<Felflickは檻の中を行ったり来たり跳ね回り、ずっとくすくす笑っている。>\n\nさあ、あのウォーロックどもにふさわしい運命をくれてやる時だ。道をたどれば、ここの西に巨大な骨の山がある。信じろ、見逃しようがない。奴らの「失敗した」実験は全部あそこに行くんだ。\n\nあそこにこの間抜けどもの亡骸を捨ててやりたい。奴らがどれほどの失敗作か、世界中に知らしめてやれ！", nil, nil, 0x9ccc7a6b, 0x95eef7e8, 0x8836fb72, nil, nil, "...mm" },
  [96438] = { "Mannoroc Covenでの戦い", "DesolaceのMannoroc Covenでの戦いを調査する。", "{name}、君の助けが必要だ。DesolaceのNigel's Pointを通りかかった我らの兄弟の一人が、Mannoroc Covenで起きた戦いの詳細を耳にした。そこにいたウォーロックとの戦いで、一方の側が強力な聖なる魔法を振るったと伝えられている。光を操る者たちが関わっていたのは間違いない。\n\nこの小競り合いに誰が関わっていたのか、もっと知りたい。もし我らの仲間が関わっていたのなら、あるいはそこで倒れたのなら……私はそれを知りたいのだ。", nil, nil, 0x16f8ad12, 0x53828f2a, 0x947ec34f, nil, nil, "...mm" },
  [96449] = { "Aeonasの秘密の隠れ家", "Menethil HarborのOld Dingyを使って、Aeonasを探す。", "そういえば、ここからずっと南に人目につかない場所を知っとるよ。誰かがNewman's Landingと呼んどると教えてくれた。もっとも、その「Newman」とやらが誰なのかは聞かんでくれ。Ol' Aeonasを探すなら、そこから始めるといい。\n\nいちばん北の桟橋のすぐ先、あそこにつないであるわしの古い小舟を使ってかまわんよ。大した舟じゃないが、泳ぐよりは早く着く。\n\nあいつに何もなかったといいんじゃが。君が行って友人の様子を確かめてくれたら、わしも安心できる。", nil, nil, 0xfec7166c, 0x2ce13332, 0x6224132b, nil, nil, "...mm" },
  [96476] = { "Aeonasを探して", "FelwoodのEmerald Sanctuaryで、Aeonas the Vindicatedの手がかりを探す。", "AeonasはFelwoodのことを何か言っていた。だから彼はそこにいるのかもしれない。あの森の南部に、Emerald Sanctuaryという小さな集落がある。誰か彼を見かけた者がいないか、そこで聞いて回るといいだろう。", nil, nil, 0xaf8071c4, 0xbac5a578, 0x8abc0364, nil, nil, "...mm" },
  [96494] = { "迫りくる嵐", "Hyjal Summitの入り口にあるBlackthorneの増援地点を見つける。", "周辺の偵察が済んだことで、君は仲間に加えるに足る有用さと信頼を示した。\n\n私はここで、Allianceにとって重要な情報を得るSI:7の活動を代表している。この情報は誰もが知れるものではない。口外は慎んでくれ。\n\nBlackthorne Pactとして知られるドルイドのカルトが近くに根を張り、彼らがWild Kingと呼ぶものに仕えて活動している。\n\nこの「Wild King」の領域を見つけ、印をつけてくれ。そうすれば確信を持ってStormwindへ報告できる。", nil, nil, 0xe5c57e46, 0xc6ea4966, 0x5fca695e, nil, nil, "...mm" },
  [96529] = { "Shawとの取引", "Blackthorne InformationをStormwindのMaster Mathias Shawのもとへ持っていく。", "君の助けは我々の偵察活動の鍵となった。この情報をStormwindのMaster Mathias Shawのもとへ届けてくれ。\n\n覚えておいてくれ。ここでの我々の活動、私の存在、SI:7の関与については、ほかの誰にも話してはならない。ここではまだ準備することが山ほどあるし、計画を順調に進めておきたいのだ。\n\n追って連絡する。", nil, nil, 0x00c54442, 0xbb26a5a5, 0x0b5db282, nil, nil, "...mm" },
  [96550] = { "戦いの記憶", "Elderwildの見晴らし台でEmbroidered Scabbardを使って老兵と話し、彼の話を聞く。", "その古びた鞘には、彫られた模様と印が施されている。退役兵が語った特徴と一致する。眼下に広がる大地の劇的な眺めは、息をのむような光景だ。\n\n退役兵の言葉を思い出しながら鞘を手に持つだけで、霊をこの記憶へと呼び寄せられるかもしれない。", nil, nil, 0xae620b44, 0x877f7c07, 0x98c24f9b, nil, nil, "...mm" },
  [96558] = { "兵士の慰め", "Mount Hyjalに埋められたBattle Cacheを掘り出す。", "あの見張り塔の砕けた石の下に、世界が燃え始めたとき、我々が急いで埋めた隠し場所がある。Hyjalから持ち出したわずかなものが、今もそこに眠っている。持っていけ。お前にはそれだけの資格がある。\n\n引く力が強まっている……山はもう以前のように私をつなぎ止めてはいない。我々が再び言葉を交わすことがあるかは分からない。\n\nお前のおかげで、私は自分が何者だったか、我々が何者だったかを思い出した。私の感謝と共に行け。そしてこの魂を、ついに安らかに眠らせてくれ。", nil, nil, 0xe607edf5, 0x69f605f5, 0xd6a6939e, nil, nil, "...mm" },
  [96559] = { "物資投下", "Fenwick TogglespringのPilot Survival Kitを見つける。", "ノームのテストパイロットなら誰でも知ってるよ。大空に飛び立つときは、最悪の事態に備えておかなきゃならないってね！\n\nだから僕らは、パイロット用のサバイバルキットなしに格納庫を出ることは決してないんだ。開けたとたんに無線で僕らの位置を本部へ知らせる、自動作動のビーコンがついてるのさ。ほかにも役立つ物資がぎっしり詰まってるのは言うまでもない。\n\nその荷物が落ちた場所を見つけられたら、ぜひすぐに開けて、中身を好きに使ってくれ。それでも僕を助けることになるんだからね！", nil, nil, 0xf9b68c03, 0xc4da7a46, 0xd7bbd2ea, nil, nil, "...mm" },
  [96561] = { "最後の願い", "Cradle of Tranquilityにある破壊されたAllianceの製材所の近くで、釣り池を見つける。", "<あなたは簡素な羊皮紙を広げる。>\n\nRowdy Redridge Rebelsの諸君へ\n\nここの木こりたちが言うには、あの池のgulperどもは競い合って餌に飛びついてくるらしい。いい魚で、食べればもっといい。この戦争が終わったら、仲間同士で釣り大会をやらなきゃな。\n\nルールは簡単だ。真ん中の島に立って、日がHyjalの一番高い峰の向こうに沈むまで釣る。\n\n一番多く釣ったやつは、夕飯用の魚のはらわたを抜かなくていい！\n\n-- Tobin --", nil, nil, 0x4174693e, 0x4ad04d6d, 0x433b69ee, nil, nil, "...mm" },
  [96602] = { "さらに不安定な魔法", nil, nil, nil, nil, 0x21b0f176, nil, nil, nil, nil, ".mmmm" },
  [96603] = { "不安定な魔法", "Motes of Unstable Magicを$N1個、DalaranのArchmage Celindraのもとへ持っていく。", "Archmage Rhoninは現在、Azeroth全土の魔力の流れの乱れを調査するため、遠方に出ておられます。大魔導師は、彼を助けるための重要な現地調査の資料集めに、あなたのような強い冒険者の助力を求めるよう私に命じられました。\n\nこのArcane Censerをお持ちください。その魔力を帯びている間、あなたが出会うであろう最も熟練した呪文の使い手や、他の並外れて強大な存在から、不安定な魔力の粒を取り出すことができます。その粒を私のところへ持ってきてくだされば、Kirin Torはあなたに恩義を負うことになるでしょう。", nil, nil, 0xd9f44e11, 0x5b11ae4f, 0x7d290c22, nil, nil, "...mm" },
  [96604] = { "大自然", "Brakk's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "Lok-tar、{class}。お前には冒険者の風格があるな。いいことだ。世界には、富と栄光を求める俺たちのような落ち着きのない魂がもっと必要だ。\n\nこの稼業でうまくやっていくには、荒野で生き抜くすべを学ばなきゃならん。お前の野外の腕前がどれほどかは知らんが、学ぶ気があるなら、一つ二つは教えてやれるだろう。\n\n火のそばに座って、楽にしてくれ。手ほどきしてやる。", nil, "さて、基本は身につけたから、次は近くの村のトレーナーたちから専門技能を学んでくるといい。新しい専門技能にふさわしいキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0xc9a7eaed, 0x1dfc83c1, nil, 0xeab943b1, "...m." },
  [96605] = { "大自然", "Kaga's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "ごきげんよう、{class}。あなたは冒険者らしい顔つきをしているな。それはいいことだ。世の中には、富と栄光を求める私たちのような落ち着きのない者がもっと必要なのだ。\n\nこの稼業で成功するには、荒野で生き抜く術を身につけなければならない。あなたの野外の技がどれほどかは知らないが、学ぶ気があるなら、ひとつふたつ教えられるだろう。\n\n火のそばに座って、くつろいでくれ。順を追って説明しよう。", "野外で生き抜くための技を身につけることは極めて重要だ。よく休み、よく備えた冒険者は、この生き方で生き残れる見込みがずっと高いのだ。", "さて、基本は身につけたから、次は近くの村のトレーナーたちから専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしいキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0x6d44875e, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96606] = { "大自然", "Lyreena's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "ごきげんよう、{class}。あなたは冒険者らしい顔つきをしているな。それはいいことだ。世の中には、富と栄光を求める私たちのような落ち着きのない者がもっと必要なのだ。\n\nこの稼業で成功するには、荒野で生き抜く術を身につけなければならない。あなたの野外の技がどれほどかは知らないが、学ぶ気があるなら、ひとつふたつ教えられるだろう。\n\n火のそばに座って、くつろいでくれ。順を追って説明しよう。", "野外で生き抜くのに必要な技術を身につけることは非常に大切です。十分に休息を取り、しっかり準備を整えた冒険者は、この生き方を生き抜ける見込みがずっと高いのです。", "さて、基本は身につけたから、次は近くの村のトレーナーたちから専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしいキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0xbbb8647e, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96607] = { "大自然", "Eleanor's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "ごきげんよう、{class}。あなたは冒険者らしい顔つきをしているな。それはいいことだ。世の中には、富と栄光を求める私たちのような落ち着きのない者がもっと必要なのだ。\n\nこの稼業で成功するには、荒野で生き抜く術を身につけなければならない。あなたの野外の技がどれほどかは知らないが、学ぶ気があるなら、ひとつふたつ教えられるだろう。\n\n火のそばに座って、くつろいでくれ。順を追って説明しよう。", nil, "さて、基本は身につけたから、次は近くの村のトレーナーたちから専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしいキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0x71b45cb3, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96608] = { "大自然", "Eric's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "ごきげんよう、{class}。あなたは冒険者らしい顔つきをしているな。それはいいことだ。世の中には、富と栄光を求める私たちのような落ち着きのない者がもっと必要なのだ。\n\nこの稼業で成功するには、荒野で生き抜く術を身につけなければならない。あなたの野外の技がどれほどかは知らないが、学ぶ気があるなら、ひとつふたつ教えられるだろう。\n\n火のそばに座って、くつろいでくれ。順を追って説明しよう。", nil, "さて、基本は身につけたから、次は近くの村のトレーナーたちから専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしいキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0x2837fcc0, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96609] = { "故郷の味", "Silvermoon Shimmerwineを$N1本、Dalaranの街のArille Azuregazeのもとへ持っていく。", "Silvermoon Shimmerwineをご存じですか？Eversongの葡萄園にしかない、繊細な風味のお酒です。故郷のもので私が本当に恋しく思うのは、これだけなのです。\n\n残念ながら、Thalassian Gateのこちら側では、とても手に入りにくいのです。\n\nある常連客が、Azshara北部のブラッドエルフから「解放してきた」と言い張る瓶を一本持ってきてくれました。冒険でその地方へ行くことがあって、私のためにもっと瓶を取り戻していただけるなら、その働きにたっぷりお礼をいたします。", nil, nil, 0x2177fad0, 0xe0add89f, 0x4eaf2dbf, nil, nil, "...mm" },
  [96616] = { "傷つき疲れた者のための薬草", "Hyjal Silphiumを$N1個集める。", "まさか、本当に？旅人がHyjalに戻ってきたなんて！\n\nとても信じられません！あなたの助けがあれば、私たちもようやくこの場所から解放されるかもしれません。東にはScourgeの残党がいて、絶えず襲撃を受け、多くの者がその穢れの犠牲になってしまいました。\n\nお願いです、{class}。あなたに頼みたいことがあります。ここから北の谷に、感染の苦しみを和らげる青い花の薬草が生えています。それを摘んで私のところへ持ってきてください。そうすれば負傷者を助けられます。", nil, nil, 0xc834be5b, 0x8e03a19a, 0x4209f9b4, nil, nil, "...mm" },
  [96622] = { "痛みのない休息", "Hyjal Silphium PoulticeをEnhoとMarukeのもとへ届ける。", "ここにいてもらえるうちに、最後にもう一つ頼みたいことがあります、友よ。私が作った湿布を、このキャンプにいる私の仲間2人に届けてもらえませんか？\n\nEnhoは左手の診療所にいます。ひどく弱っていますが、感染に打ち勝てるとまだ望んでいます。体力を取り戻す助けになればと、スープを匙で飲ませているのです。\n\nもう一人はMarukeです。\n\n<Ortakはしばらく黙ってうなだれる。>\n\n彼女はここから北の、残り少ない乗騎を置いている場所にいます。", nil, nil, 0xb9e4ceb9, 0xc848e3e9, 0x462893c6, nil, nil, "...mm" },
  [96626] = { "キャンプ101：Cooking", "GoldshireのTomasと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", "良い焚き火は、あらゆる良いキャンプの土台です。", "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0x48b91f09, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96627] = { "冒険者", "Goldshire付近にいるSam Sarsparillaと話してください。", "{name}、あなたはこれまで守り手としての力量を示してきた。だからこそ、今ひとつ変わった任務を託したい。\n\nGoldshireの近くの道沿いに、新顔の冒険者がいると聞いた。行って、彼が何をしているのか見てきてくれ。", nil, "見回ってくれて助かるよ、{class}。あの元帥はただの心配性なんだ。\n\nなあ、あんたも冒険者って顔をしてるな。キャンプについて学んでみないか？", 0x1afc3318, 0x24f0776f, 0x24463491, nil, 0xeb1c22f1, "...m." },
  [96628] = { "冒険者", "Supply BundleをKharanos付近にいるEric Brighthammerに届けてください。", "待て、{name}。あのトンネルに挑む前に、もうひとつ頼みがある。\n\nうちの山岳兵たちから、Kharanosのすぐ外に冒険者がひとり現れたと報告があった。この物資を彼に届けてくれないか？", "荒野でのキャンプについて学びに来たのですか？", "山岳兵からのものだって？ ああ、ありがたく使わせてもらうよ。ありがとう、{class}。\n\nなあ、あんたも冒険者って顔をしてるな。キャンプについて学んでみないか？", 0x1afc3318, 0xbfabdfa9, 0x1f02236b, 0xf7a7f9bd, 0x5f83030c, "....." },
  [96629] = { "キャンプ101：Cooking", "KharanosのGremlock Pilsnorと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", "良い焚き火は、あらゆる良いキャンプの土台です。", "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0xfb18b446, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96630] = { "冒険者", "日誌をDolanaar付近にいるLyreena Duskbladeに届けてください。", "<日誌はごくありふれたもので、聞いたこともない誰かの生活と冒険が綴られている。\n\nキャンプについての記述がいくつもある。どうやら、なかなか……楽しいものらしい。>", "荒野でのキャンプについて学びに来たのですか？", "それは俺の日誌か？ しばらく前からなくしてたんだ。ありがとう、{class}。\n\nなあ、あんたも冒険者って顔をしてるな。キャンプについて学んでみないか？", 0x1afc3318, 0xc5322669, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96634] = { "キャンプ101：Cooking", "DolanaarのZarrinと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", "良い焚き火は、あらゆる良いキャンプの土台です。", "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0xa03560df, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96638] = { "冒険者", "Shen'dar Village付近にいるRaan Wildwindと話してください。", "あなたのような冒険者が、Thendal Groveの安全な場所を離れて栄光と富を求めることが、ますます増えています。そんな冒険者のひとりが、Thendal Groveから南西へ延びる道沿い、Shen'dar Villageの外に野営地を作っています。\n\n彼を訪ねて、あなた自身の旅に役立つことを何か学んでくるとよいでしょう。", nil, "よく来たな！", 0x1afc3318, 0x72c75d4e, 0x5990b6bd, nil, 0x47da9bb0, "...m." },
  [96646] = { "キャンプ101：Cooking", "Shen'dar VillageのZerril Softbreezeと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", "良い焚き火は、あらゆる良いキャンプの土台です。", "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0x8b592b5f, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96652] = { "冒険者", "日誌をRazor Hill付近にいるBrakkに届けてください。", "<日誌はごくありふれたもので、聞いたこともない誰かの生活と冒険が綴られている。\n\nキャンプについての記述がいくつもある。どうやら、なかなか……楽しいものらしい。>", "荒野でのキャンプについて学びに来たのですか？", "それは俺の日誌か？ しばらく前からなくしてたんだ。ありがとう、{class}。\n\nなあ、あんたも冒険者って顔をしてるな。キャンプについて学んでみないか？", 0x1afc3318, 0x19108351, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96655] = { "キャンプ101：Cooking", "Razor HillのCook Torkaと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", nil, "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0x4f2cbefa, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96656] = { "冒険者", "Brill付近にいるEleanor Shackletonと話してください。", "{name}、お前はこれまでScarlet Crusadeとの戦いで信頼に足ることを示してきた。だからこそ、今ひとつ変わった任務を託したい。\n\nBrillの近くの道沿いに、新顔の冒険者がいると聞いた。行って、彼女が何をしているのか見てこい。", nil, "見て分からないかもしれないが、俺はScarlet Crusadeとは何の関係もない。次に荒野へ出かける前に立ち寄っただけの、ただの冒険者さ。\n\nなあ、あんたも冒険者って顔をしてるな。キャンプについて学んでみないか？", 0x1afc3318, 0x60140125, 0x7846cd95, nil, 0xbb601ab5, "...m." },
  [96658] = { "キャンプ101：Cooking", "BrillのWilliam Pickmanと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", "良い焚き火こそ、良い野営地の基本だ。", "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0xca2cf982, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96659] = { "冒険者", "Supply BundleをBloodhoof Village付近にいるKaga Wildhoofに届けてください。", "お待ちなさい、{name}。出発する前に、もうひとつお願いがあります。\n\nKaga Wildhoofという名の冒険者が、Bloodhoof Villageのすぐ外に野営しています。彼女には以前大いに助けてもらったので、今こそ恩を返す機会だと思うのです。この物資を彼女に届けてもらえませんか？", "荒野でのキャンプについて学びに来たのですか？", "Chief Hawkwindに言われて来たのか？ あの時、礼はいらないと言ったんだが、聞いてくれなかったらしい。ありがとう、{class}。\n\nなあ、あんたも冒険者って顔をしてるな。キャンプについて学んでみないか？", 0x1afc3318, 0x8ee06ce3, 0xc65676fe, 0xf7a7f9bd, 0x113825f8, "....." },
  [96661] = { "キャンプ101：Cooking", "Bloodhoof VillageのPyall Silentstrideと話して、料理人になる方法を教わってください。", "で、キャンプについてもっと知りたいってわけか？ いいことだ、{class}。どんな冒険者もまず最初にやるべきことは、料理人になって焚き火の起こし方を覚えることさ。\n\nCookingってのは、うまいものを作るだけじゃない。野営地の土台でもあるんだ。", nil, "これがあれば、荒野のどこにでもキャンプを張れる。覚えたのは基本だけだから、周りにあまりたくさんの家具は置けないがな。\n\n料理の腕を上げれば、もっと大きな焚き火の作り方を覚えられるかもしれない。\n\n他の専門技能のトレーナーからも、その技能に通じていれば、キャンプの家具の基本を学べるぞ。", 0x61f383d0, 0xbe1a3274, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96666] = { "巣穴での絆", "Barkskin Burrowとの評判を友好まで上げる。", "Barkskin、お前のこと前より良く言う、友よ。でも、お前やること、まだある。\n\n我らの敵に手を上げろ。我らの流儀を敬え。\n\n我ら、よく見ている。それから、お前にもっと話すことある。", nil, nil, 0x1dd1aa09, 0xb3e8554e, 0x1872ff19, nil, nil, "...mm" },
  [96674] = { "雌羊がはぐれた", "Escaped Sheepを$N1匹捕まえて連れ戻す。", "<近づくと、Mirtは目を丸くする。>\n\nわあ、誰？ママが新しい人が来たって言ってた。Scourgeをいっぱいやっつけて、すっごく強いんだって！熊と戦ったことある？*息をのむ* ドラゴンとも！？ぼ、ぼく……\n\n<Mirtは後ろを振り返り、恥ずかしそうにする。>\n\nもしかして……手伝ってくれる？ぼく、羊の番をしてなきゃいけなかったんだけど、泥でドラゴンを作ってたら逃げちゃったんだ。羊たちは「あっち」側にいるの。ぼくはあっちに行っちゃだめなんだ。ママが、怪我するかもしれないって。羊を探してきてくれる？", nil, nil, 0xcd7a4e99, 0xeed2ec15, 0xd520500d, nil, nil, "...mm" },
  [96676] = { "Blackthorne Pactの封印を解く", "Alliance EquipmentをHyjalのJohun \"Punchy\" Dillasのもとへ持っていく。", "さて、密偵よ、君は昇進だ。\n\nこの新しい命令書を、HyjalのベースキャンプにいるJohunのところへ届けてくれ。中には、Summitでの我々の作戦に彼が必要とする追加の装備も入っている。\n\nこの件での君の助力は、Kalimdorにおける我々の全体戦略にとって極めて重要だ、{name}。ぐずぐずするな。\n\n下がってよい。", nil, nil, 0x4428a3f9, 0xbfe6302f, 0xbc3d0e64, nil, nil, "...mm" },
  [96735] = { "乾杯！？", nil, nil, nil, nil, 0x0f38dabc, nil, nil, nil, nil, ".mmmm" },
  [96770] = { "呪術医の首", "Witch Doctor Zum'rahを倒し、Zum'rah's HeadをDalaranにいるArchmage Lan'dalockのところへ持って行く。", "Zum'rahという名で通っているトロールの呪術医がいる。そのトロールとは因縁があってな、君に始末してもらいたい。\n\nTanarisの砂漠の奥深くにある、Sandfuryの砦Zul'Farrakへ向かえ。中でZum'rahを見つけて倒すのだ。奴の首を無傷のまま持ってくれば、相応の報酬を払うと約束しよう。", nil, nil, 0x40b5f7a9, 0xb988bb33, 0xea4ddda7, nil, nil, "...mm" },
  [96771] = { "Highborneの復讐", "Krol'dok Strongholdへ赴き、Zalfan Moonshadowを倒す。", "南東のRivergladesと呼ばれる地方に、Krol'dok Strongholdという場所がある。Zalfan Moonshadowというhighborneが、そこでTwilight's Hammerと行動を共にしているのが目撃されている。\n\nこの愚か者をこの世から消し去ってくれるなら、たっぷり礼をしよう。奴は狂信者どもとつるみ、盗んだ秘術の知識を奴らのために使うことで、highborneの誇り高き血統に恥を塗っている。ただでさえ我らの生き残りは少ないというのに、奴のような虫けらに我らの良き名を汚されてはたまらぬ。", nil, nil, 0x9b77b441, 0x0210fb3d, 0x59c6ab25, nil, nil, "...mm" },
  [96772] = { "ドラゴンの日誌", "Alcaz Prisonの奥深くからZarla's Journalを取り戻す。", "Timearと私は、KalimdorのAlcaz Islandと呼ばれる一帯を遠見の術で探っていたのだが、そこに強大な魔法の使い手がいることはほぼ確かめられた。問題のメイジは我々の探査を打ち消してしまったが、その前に、何かの書物らしき姿を垣間見ることができた。古代の竜の文字で書かれた日誌だったと思う。\n\nその本に何が書かれているのかは分からないが、ぜひ研究したい。Alcaz Islandの地下に隠された牢獄へ行き、その本を取り戻してきてほしい。", nil, nil, 0x8db2fe13, 0x5484c229, 0x3a3ecf49, nil, nil, "...mm" },
  [96773] = { "The Coldbringer's Eye", "Razorfen DownsからThe Coldbringer's Eyeを取り戻す。", "Razorfen Downsと呼ばれるquilboarの巣窟の奥深くに、Lich Kingの僕が住み着いている。奴が「The Coldbringer's Eye」という遠見の宝珠を使い、よそにいる配下の手下どもの動きを指図していることは、我々も把握している。\n\nRazorfen Downsに入り、我々に代わってColdbringer's Eyeを取ってきてくれ、{class}。Kirin Torは、この秘宝を研究し、その内部の仕組みを解き明かすためなら、手に入れるのに惜しみなく金を払うだろう。", nil, nil, 0x807d643a, 0xc02af882, 0x03f459cb, nil, nil, "...mm" },
  [96774] = { "Ancient Gurubashi Idol", "Drowned CityからAncient Gurubashi Idolを取り戻して下さい。", "Stranglethorn Valeの古のGurubashiは、黒い血の魔術の達人だった。噂じゃ、奴らは純粋なtruesilverの偶像を使って、そのひどいブードゥーを操ってたらしい。\n\nこのMazu'kon様は、その偶像を一つ手に入れたくてたまらねえ……学問のためさ、分かるだろ。仲間を何人か集めて、Stranglethornの沖の海から突き出してる、あの沈んだ都市でちょいとかっさらってきてくれねえか？ あの中で一番偉そうなプリーストを倒せば、オレの探してるものを持ってるはずだ。", nil, nil, 0x5f76897d, 0x4a847e99, 0xf74ccc84, nil, nil, "...mm" },
  [96775] = { "Zum'rah's Head", "Witch Doctor Zum'rahを倒し、Zum'rah's HeadをMulgoreにいるMazu'konのところへ持って行く。", "Mazu'kon様はな、Zum'rahって名の呪術医に恨みがあるんだ。で、お前ならそいつを手伝ってくれると思ってるんだぜ。\n\nZum'rahは、ずっと南のTanarisの砂漠にあるSandfuryの都Zul'Farrakで、ろくでもないブードゥーばかりやってやがる。そこへ行け。Zum'rahを殺して、奴の首を持ってこい。\n\n信じろよ、兄弟。奴の首は肩の上に乗ってるより、おれの小屋の外で槍に刺さってる方が、世の中ずっと良くなるってもんだ。", nil, nil, 0x8614fa93, 0x101e780b, 0x454a2ac8, nil, nil, "...mm" },
  [96776] = { "An'she's Radiance", "MaraudonからAn'she's Radianceと呼ばれる水晶を取り戻す。", "私は幻を見た。\n\nMaraudonと呼ばれる地の奥深く、earth song fallsを越えた先に、輝く白い水晶に満ち、強大な巨人たちに守られた広間がある。その広間の最も高い所に、ひときわまばゆい輝きを放つ水晶がある。それは太陽神の化身であり、Earthmotherその人の右目、An'sheなのだ。\n\n私はその輝きを夢に見た。それが私を呼んでいるのだ。{class}よ、An'she's Radianceをその場所から運び出し、本来あるべきこの地、Mulgoreの開けた空の下へと持ってきてほしい。", nil, nil, 0x29fa6e04, 0x3d4715f6, 0x1a4626c3, nil, nil, "...mm" },
  [96779] = { "Syndicateへの破壊工作", "Hillsbrad FoothillsのDurnholde Keepの中でLord Tomasを見つけて倒して下さい。その後、Myrokos Silentformのところへ戻って下さい。", "時に、{race}よ、急所への一太刀で敵は倒れる。組織についても、同じことがしばしば言える。\n\n我々の諜報員が、Syndicateの中に重要な標的を突き止めた。Lord Tomasという名の男だ。\n\n奴はHillsbrad FoothillsにあるDurnholde Keepの運営において、重要な役割を担っている。Ravenholdtの役に立ちたいなら、Durnholdeへ行き、奴を始末しろ。早く、そして静かであるほど良い。", nil, nil, 0x12459469, 0xd843986f, 0xd52e350a, nil, nil, "...mm" },
  [96781] = { "どういうつもりだ？", "Barton's Scouting Reportを彼の懐から盗み取って下さい。その後、その報告書をRavenholdt ManorのMyrokos Silentformのところへ持って行って下さい。", "Syndicateの偵察隊が、Bartonという男に率いられてAlteracの廃墟をうろついているのを確認した。\n\n奴らは明らかに何かを探しているが、奴の偵察報告書を読まなければ、それが何かは分からない。\n\n奴を殺すのではなく、報告書をスリ取ってほしい。Bartonが死ねば、我々が嗅ぎつけていることがSyndicateに知れ、奴らは必ず痕跡を消すための対抗策を講じるだろう。\n\n奴を探すなら、おそらくStrahnbradのSyndicateの中にいるはずだ。", nil, nil, 0xe4f9042e, 0x63217e37, 0x8e8d9103, nil, nil, "...mm" },
  [96782] = { "極秘の回収", "Alteracの廃墟でBlade of House PerenoldeとRoyal Aegis of Perenoldeを見つける。それから、それらをMyrokos Silentformに届ける。", "どうやらここにいる我らが友Bartonのおかげで、事はとても簡単になったようだ。奴はAlteracの遺跡にあるPerenolde家の家宝を2つ狙っている。剣のBlade of House Perenoldeと、盾のRoyal Aegis of Perenoldeだ。\n\n報告によれば、その武具は遺跡の中にある2つの塔にあるらしい。Syndicateより先に手に入れたほうがいい。\n\n遺跡を占拠しているogreは獰猛だが、お前なら刃を血で汚すことなく、奴らの横をすり抜けられると信じている。", nil, nil, 0x38463dcf, 0x0dd136cc, 0xbaff77cb, nil, nil, "...mm" },
  [96783] = { "侵入口", "Stromgarde Keepに潜入するため、Northfold ManorからSyndicateの制服を盗んで下さい。", "Stromgarde KeepはSyndicate最大の拠点の一つだ。組織の最も重要な取引の多くが、その城壁の内側で行われている。\n\nArathi HighlandsのどこかでSyndicateの者同士の取引が行われるという知らせを受けた。その取引の詳細は、きっとStromgardeのどこかで見つかるはずだ。\n\n疑いを招かずに砦へ潜入するには、変装が必要だ。砦の外、Northfold ManorにいるSyndicateの連中から手に入れられないか探ってみろ。", nil, nil, 0x1b0f8afe, 0xaa986c18, 0x7b8b0be2, nil, nil, "...mm" },
  [96784] = { "変装の達人", "Syndicateの一員に変装したまま、Stromgarde Keepの中で秘密の取引を知っている人物を見つけて下さい。", "<あなたは、Stromgarde KeepでSyndicateが進めている重要な取引について調べるようにというMyrokosの指示を思い出す。変装していれば、Syndicateの者たちとある程度自由に話せるはずだ。きっと、誰かが何かを知っている。>", nil, nil, 0x87afd4b0, 0x839d37e0, 0xac13dcec, nil, nil, "...mm" },
  [96785] = { "何とも言えない", "Anastasiaに秘密の取引の詳細を明かさせるため、Stromgarde Keepの中で説得材料になる物を見つけて下さい。", "お前、何様のつもりだ？ いきなり現れて、公の仕事に首を突っ込むとはな。\n\nちゃんとした理由もなしに、上の連中の取引について新入りに話すつもりはねえ。何か大事なもんか、価値のあるもんを持ってこねえ限り、お前に話すことは何もねえよ。", nil, nil, 0x21897a89, 0xe27114b7, 0xce26588b, nil, nil, "...mm" },
  [96786] = { "Syndicateへのおとり捜査", "秘密の取引を阻止し、Syndicateへ渡される品物を奪って下さい。その後、Ravenholdt ManorのMyrokos Silentformのところへ戻って下さい。", "FalconcrestがThoradin's wallの南側に、受け渡しのために何人か送り込んだ。何を受け取るのかは知らねえ。関わってる奴ら全員が完全に秘密にしてるんだから、よっぽどいい物なんだろう。受け取りに行く連中でさえ、それが何なのか知らねえと思う。\n\n俺が知ってるのはそれだけだ。話したことを後悔させるなよ。", nil, nil, 0x54ce55fd, 0x3c52e102, 0x27700057, nil, nil, "...mm" },
  [96796] = { "森の工房", "Spare PartをHyjal下部にいるKaylaenaという技師のもとへ持っていく。", "これは、丘に住む技師Kaylaenaの役に立ちそうな物です。師であるYaelyを失ってから、彼女はほとんど姿を見せません。\n\n北の丘で彼女の工房を探してください。大いなる戦いでArchimondeが倒れた後、二人は自分たちで持ち帰れる物を拾い集め、この麓の機械の多くをすっかり漁り尽くしたのです。\n\nこの残骸をここで錆びさせておくより、新たに役立てる方がよいでしょう。あなたの使いは、金属に息を詰まらされていた場所に新たな命を芽吹かせる助けとなるのです。", nil, nil, 0x918594f1, 0x5041b322, 0xeabc482c, nil, nil, "...mm" },
  [96797] = { "孤児", "Blasted LandsのNethergarde Keepへ赴き、Sergeant Dannethを見つける。", "私たちは預かっている子どもたちの多くについて、生き残った家族を探そうとしています。時には希望の持てる知らせが見つかることもあります。ここにいるRandalに、生き残った身内がいるかもしれないという知らせを受けました。その男性の名前はDannethといって、Nethergarde Keepに駐屯している兵士です。誰かにそこまで行って、その方を見つけてきてもらいたいのです。\n\nできれば、甥を迎えに来るようDannethを説得してください。二人は一度も会ったことがないと思いますが、それでも家族は家族ですし、Randalは彼のもとにいるべきなのです。", nil, nil, 0x06d9ea43, 0x3a64b856, 0x74fdcc7c, nil, nil, "...mm" },
  [96798] = { "闇の中へ", "Nethergarde Keepの南東にあるSerpent's Coilの洞窟のどこかでSergeant Dannethを見つける。", "Sergeant Dannethが最後に目撃されたのは、Nethergarde Keepのすぐ南、Serpent's Coil付近を部隊と巡回していた時だ。部隊員の一人がひどい傷を負ってよろめきながら砦に戻り、部隊は全員殺されるか捕らえられたと言った。残念ながら、その兵士は数時間後に死んだ。\n\nDannethが死んだという確証はないが、望みは薄い。教団の巣窟に攻め込む人員は割けないが、君があの男を探しに行きたいというなら、その助力を断りはしない。", nil, nil, 0x713cd83f, 0x9e8fb5bf, 0x0ff8b087, nil, nil, "...mm" },
  [96799] = { "重い責任", "Nethergarde KeepのSergeant Dannethと話す。", "<Lieutenant Connarは、あなたがここに来た理由を話すのに耳を傾ける。>\n\nでは、DannethにはDalaranに孤児となった甥がいるのか？まだその件で彼と話していないなら、話しておくといい。とても子育てをするような男には見えないが、驚かされるかもしれん。\n\n彼が回復してからその子を迎えに行きたいというなら、そのための休暇を取ることを許可しよう。", nil, nil, 0xcd6be72b, 0x6157b976, 0xf44bbe90, nil, nil, "...mm" },
  [96800] = { "期限切れ", "Scarlet MonasteryからThe Lost Magic of the Runemastersという本を取り戻す。", "そこのあなた、{class}。手を貸してほしい件があります。\n\nちょうど今、Grim Batolの古代Wildhammerのルーンマスターについての論文を書いていて、研究を完成させるのに必要な特定の書物があるのです。我々の台帳によれば、Doanという名のメイジがThird Warの前に古いDalaranの図書館からその本を借り出し、一度も返していないのです！\n\nArcanist Doanは今、Tirisfal GladesのScarlet Monasteryに立てこもっています。この本を取り戻してくれれば、十分にお礼をします。", nil, nil, 0xc02ef2a8, 0x6080a32a, 0x72b14b39, nil, nil, "...mm" },
  [96811] = { "影からの脱出", "Sergeant Dannethを護衛してSerpent's Coilの洞窟から連れ出し、Nethergarde Keepまで送り届ける。", "もう準備はできたと思う。あなたの準備ができたら出発しよう。", nil, nil, 0xd6aa55ba, 0x81655720, 0x3205c370, nil, nil, "...mm" },
  [96812] = { "水よりも濃い", "DalaranのOrphan Matron Ariaのもとへ戻り、Sergeant DannethがRandalを引き取るつもりだと伝える。", "ああ……ああ、あの子を引き取ろう。あの子は家族で、あの子には俺しかいない。もう少し回復に時間がかかるが、動けるようになりしだい休暇を取ってDalaranへ向かう。\n\n寮母のところへ戻って、俺がそちらへ向かっていると伝えてくれ。兄弟の子が無事に、強く育つよう、できる限りのことをする。\n\n誓おう。", nil, nil, 0x74278638, 0xd3e836dc, 0x813783b0, nil, nil, "...mm" },
  [96821] = { "一目散", "Durotar南部でRidgeshade Creepersを6体とRidgeshade Lurkersを6体倒し、Razor HillのGar'thokに報告してください。", "近頃はRazor Hillから来る旅人がどんどん減っている。scorpidどもは昔から厄介だったが、今度は道沿いに蜘蛛が巣を作っていると聞く。\n\n北へ向かうことがあれば、途中で蜘蛛を何匹か倒してくれ。それからRazor Hillに、道が少しは安全になったと知らせてやってくれ。", nil, "ペオンどもはしばらく前から南へ行くのを怖がっていたんだ、{name}。お前が道を少し切り開いてくれたから、これで奴らを仕事に戻せる。", 0xb84a70d7, 0x3a400289, 0x05f6951d, nil, 0xd8c3f0b4, "...m." },
  [96822] = { "名誉のために", "Tiragarde Keepの外れでRaider's Battleaxe、Raider's Bow、Raider's Shieldを集め、Razor HillのTurrocに届けてください。", "Tiragarde Keepを襲撃した時、我らはHordeの勇敢なウォリアーを大勢失った。人間どもが廃墟の守りを固めた今、彼らの死をきちんと称えるための亡骸を回収することもできん。\n\n砦を囲む廃墟へ行き、倒れた同胞が残した武器を探してこい。名誉ある場所に飾るのだ。", "頼んだことは済んだか？", "この戦士たちのことは、いつまでも忘れられることはない、{name}。お前がそれを確かなものにしたのだ。", 0x312a6de6, 0x12f27d5e, 0x59e8004e, 0x914533e6, 0xfc5f93be, "....." },
  [96825] = { "この果実は噛み返す", "Razor HillのCook Torkaは、町の西にあるRazormane GroundsでPrickly Pear Fruitを8つ集めてほしいと言っています。", "ハンターや漁師たちは部隊のために旨い食べ物をたっぷり持ち帰ってくれるが、甘いご馳走はめったにない。\n\nとげがあって美味い実をつけるサボテンを見かけたことがある。だが、それが生えているのは西の丘だけで、そこには忌々しいquilboarどもが野営している。quilboarどもをかいくぐって、その実をいくらか持ってきてくれ。気をつけろよ。その実はquilboarどもと同じくらいとげだらけだからな！", "果実は見つかったか？", "これで何かおいしいものを作って、種は植えるために取っておこう。いつかOrgrimmarのあちこちでウチワサボテンの実がなるようになるぞ！", 0x5d0fb368, 0x56b9c042, 0x2c431c3a, 0xa390104c, 0x879b29b5, "....." },
  [96830] = { "Farsightの導き", "Mount Hyjalの北西でHordeの痕跡を探す。", "人間の悲鳴が頭上高くから聞こえた時、俺の斧はまだ悪魔の血肉を滴らせていた。\n\n見上げると、この男が巨大なキメラの爪にぶら下がっていた。男は激しく抵抗し、獣は掴みそこねて男を落とした。\n\nあの高さからでは、どんなウォリアーも生きては帰れん。敵であろうと尊厳には値する。だから安らかに逝けるよう、日陰まで引きずってやった。\n\n俺は遠見師たちの幻視を追っている。仲間はまだHyjalに、遥か北西にいる。\n\n俺の代わりに、残るHordeを探してくれ。名誉が俺をここに留めている。", nil, nil, 0xcf7b38b1, 0xddcbdd46, 0x6134af41, nil, nil, "...mm" },
  [96833] = { "毒の顎", "Ghansurokという凶暴なキマイラについての警告を、山にいるほかの者たちに伝える。", "Gh……Ghan。Sur……Okk……Ghansurok。それがあの邪悪なキメラの名前だ。ここでなら何とかなると思ったんだ……うっ……一人でな。とんでもなかった。宙に掴み上げられちまった。\n\n見つけた一番近い目に短剣を突き刺してやったら、木のてっぺんよりも高いところから落ちた。\n\n今回、身の丈に合わないことに手を出したのは俺だけじゃない。はは……うっ……笑っちゃいけないな、ただでさえひどく痛むのに。\n\n折れた骨なら治せる、だが……毒が……ひどすぎる。\n\n警告を伝えてくれ。頼む！", nil, nil, 0x45916c91, 0xad3860db, 0xa460a2e5, nil, nil, "...mm" },
  [96873] = { "厄介の種", "Sen'jin VillageのPa'zulaは、Luminous Residueを3つ集めてほしいと言っています。Luminous Residueは、Echo Islesのトロールが落とすHexed Pendantsを分解して手に入れることができます。", "ここから東のトロールたちは、呪術師Zalazaneに意志を奪われてしまった。奴は捕らえた者の心をつかんでおくために多くの残酷な魔法を使うが、お気に入りの手口のひとつが、邪悪な束縛の呪文を巻きつけたペンダントを身につけさせることだ。\n\nこのペンダントから魔法を剥ぎ取って付呪の腕を磨き、その結果を持ってきてくれ。それと、自由が惜しいなら、うっかり首にかけたりするなよ！", "何を持ってきてくれたんだ、{name}？", "見事な働きだ。殺されたトロールたちは気の毒だったが、束縛の呪文が取り除かれた今、彼らの魂は安らげるだろう。", 0xdbeec7f9, 0x2e3399cb, 0x4f2abab1, 0x777ed8a4, 0xd6297264, "....." },
  [96874] = { "これがSpinal Axeだ", "OrgrimmarのUg'thokは、Thunder Ridgeの獣からWeathered Spinesを5つ、それにRough Grinding Stonesを5つ集めてほしいと言っています。", "Thunder Ridgeのでっかい獣を見たことがあるか？ あいつらの背中の棘は、強力な斧の頭を作るのにぴったりだとずっと思ってるんだ。Saruに話したら笑われたが……あいつに何がわかるってんだ!?\n\n鍛冶の修業の一環として、俺を手伝ってくれ！ その棘をいくつか、それを研ぐための砥石と一緒に持ってきてくれ。", nil, nil, 0xf6bb3113, 0xf3ac90a4, 0xc9a1f75b, nil, nil, "...mm" },
  [96875] = { "Thunder Ridgeの獣", "OrgrimmarのKamariは、Thunder Ridgeの獣からRough Lizard Hideを5枚、それにCured Light Hidesを2枚集めてほしいと言っています。", "Orgrimmarは常に広がり続けているんだ、{class}。そしてpeonどもが新しい建物の壁や屋根を覆う皮を必要とする時、俺のところへ来るってわけだ！\n\nThunder Ridgeのトカゲの皮はたいてい鎧にするには厚すぎるが、建材としては最高なんだ。そいつらの皮を、軽くなめした皮をいくつかと一緒に持ってきてくれ。お前の革の腕前を見せてもらおうか！", nil, nil, 0x6150b99e, 0x6f6f97d3, 0x8796ce18, nil, nil, "...mm" },
  [96876] = { "Ukor's Lost Pack", "荷物をDurotar南部にいるUkorに返してください。", "荷袋の垂れ蓋に沿って、「Ukor」という名前が雑に縫い付けられている。", nil, nil, 0xae92df38, 0x533f75f6, 0x6bd7c611, nil, nil, "...mm" },
  [96877] = { "Halikor's Hoof", "Halikor's HoofをOrgrimmarへ届けてください。", "この巨大な蹄は、強大なトカゲに勝利した証となる。", "何か？", "なんという戦利品だ、{class}！ さぞかし激しい戦いだったろう！", 0x795887e1, 0xda5a81ff, 0x4475e6e3, 0x0c07a888, 0x6e0703c3, "....." },
  [96895] = { "Argentの使節", "Undercityの入口近くにいるArgent Dawnの一員を見つけてください。", "聞いたかどうか知らないが、ついさっきArgent Dawnの使者が2人ここを通っていった。Argent Dawnは嫌いじゃないが、奴らが監視もなしにTirisfalを嗅ぎ回るのは気に入らない。どちらもForsakenだったが……だからといって不安が和らぐわけじゃない。\n\nそのうちのひとりが、ついさっきここを通って南東へ向かった。その方角の街の外れで、Scourgeの教団員の一団が嗅ぎ回っている。あの2人がそいつらのことを聞いたなら、間違いなく目をつけたはずだ。", nil, "身を低くして、見つからないようにしろ、{class}。このカルト信者どもは侮れないぞ。", 0xdf68a7ca, 0x2508ce6f, 0x46ae3d29, nil, 0x5a1a2923, "...m." },
  [96896] = { "正しき大義", "Danitha MorrとLeonid Barthalomew the Reveredの会話を見守ってください。", "Danithaと私は、Naxxramasが攻めてきたとき、Undercityを守るためにScourgeと戦った。あの日、我々は多くの良き友を失った。この砦の名の由来となった英雄、Garek Bandarionもその一人だ。\n\n彼は、パラディンとして光を振るうすべを再び見いだした、最初のForsakenだったかもしれない。彼の遺志と可能性が、ここでDanithaと彼女の仲間たちに受け継がれているのを見ると、心強く思う。\n\n他のForsakenたちも同じように感じてくれればいいのだが……", nil, "しばらくここに留まって他の友人たちと話をするつもりですが、近いうちにEastern PlaguelandsのLight's Hope Chapelへ戻ります。もしそちらへ行くことがあれば、ぜひ顔を見せてください。腕の立つ冒険者の助けは、いつでも歓迎ですから。", 0xb14e63d6, 0x07dc792c, 0x3aaba567, nil, 0xf3a7963d, "...m." },
  [96897] = { "Cult of the Damned", "Tirisfal GladesでDark Neophyteを$N1人とDark Enforcerを$N2人倒してください。", "Scourgeは我々の地を蝕む病だ。そして奴らに仕える生者どもは、その中でも最悪だ。Tirisfalの民は、心なき死者とScarlet Crusadeの間で、ただでさえ手一杯なのだ。善を成したいなら、この屑どもを始末するのを手伝ってくれ。", "Scourgeに仕える生者には、格別の嫌悪を覚える。奴らには立ち去る自由意志があるというのに、力と不死の約束が、奴らから理性と道徳を奪ってしまったのだ。", "助けてくれてありがとう、{class}。Lordaeronの歴史を繰り返したくないなら、こうした脅威が現れたときには警戒を怠ってはならない。", 0xb7d2480d, 0x5e8b58f6, 0xcef83677, 0x5254018a, 0x346b816b, "....." },
  [96898] = { "戦争の残骸", "Tirisfal GladesでNecrotic Crystal Fragmentを$N1個集めてください。", "Naxxramasの城塞がこの街に襲いかかり、Forsakenを地図から消し去ろうとしたのは、そう昔のことではない。Forsakenの未来を守るため、ForsakenもArgent Dawnもあの日多くを失った。\n\n戦いのさなか、Naxxramasの頂に据えられていた巨大なネクロティックの集束水晶が砕け、その破片がこのあたり一帯に散らばった。教団員どもの狙いはそれだろう。破片を回収して、Scourgeの手に渡らないようにするのを手伝ってくれ。", "あの水晶にはあまり直接触れないほうがいい。砕けて力を失っていても、この死霊の水晶に残る魔法は極めて危険だ。", "ありがとう。これでこの辺りのScourgeの活動を遅らせられるはずだ。Tirisfalの住人たちは何年もこの水晶を地面から引き抜くことになるだろうが、最も目立つものを取り除くだけでも役に立つ。", 0x91003497, 0x26a56997, 0x244a6298, 0x408b3f9b, 0x894f0f43, "....." },
  [96899] = { "Bandarion Keep", "Tirisfal GladesのBandarion KeepでLeonid Barthalomewと会ってください。", "今日ここで、あなたはArgent Dawnの大義のために大きなことを成し遂げてくれた。感謝する。Bandarion Keepの砦をどれほど知っているかわからないが、私と司令官は、そこに住むパラディンたちに会うためにそちらへ向かっていた。Cult of the Damnedがいると知る前のことだ。\n\nArgent Dawnと我々の使命についてもっと知りたければ、ここから北西のBandarion Keepにいる私の司令官を訪ねてくれ。私はここに残って、この後始末をつける。", nil, "この場所には思い出がたくさんあります。ここはかつてArgent Dawnが守っていた場所です。Scourgeが最近Tirisfal Gladesへ攻め込んだとき、私たちはここから多くの戦いや小競り合いに備えたのです。\n\nPlaguelandsへ撤退したとき、ここが荒れ果ててしまうのではないかと心配しました。その心配は当たっていましたが、Danithaと彼女のパラディンたちが今ここの管理を引き継いでくれて嬉しく思います。\n\n彼女はこの砦に……共通の友人の名前までつけたのですよ。", 0x48578fb3, 0x80cd9bdb, 0x27457914, nil, 0x17570e1d, "...m." },
  [96912] = { "名誉の戦場：第1週", "決闘に10回勝つ。", "よう相棒、さあ寄ってきな！剣のどっちの端をどこに向けりゃいいか、分かってそうな顔してるじゃないか！\n\nちょうどいいことに、選りすぐりの戦士にしか達成できない挑戦が山ほどあるんだ。いっちょ挑んでみるかい？", nil, nil, 0xfe280b34, 0xc8fd5d0d, 0x8e3c78da, nil, nil, "...mm" },
  [96913] = { "名誉の戦場：第2週", "Warsong Gulchの戦いを3回完了する。", "またあんたか、え？次の試練の準備はいいかい？血を見るのが苦手じゃないといいんだが。今回はあんたが血を流す羽目になるかもしれないぜ……できれば、先に相手の連中に流させてほしいけどな。", nil, nil, 0xfe280b35, 0xb9209b33, 0x90a36567, nil, nil, "...mm" },
  [96930] = { "Capricious Corvid", "Curious Crowのもとへ戻る。", "Ve'han Talongraspが今操る力に対抗するには、実に強大な魔法が必要です。Velicianが奪った杖が、鍵となるかもしれません。\n\nドルイドとしての私の力は、もはやかつてのものではありません。この悪を止めるには、山に住まう神々の助けが必要となるでしょう。\n\n山の上で出会ったカラスのもとへ戻ってください。彼女は賢いのですが、野生の霊たちは、恐ろしい脅威を前にしても常に気まぐれなのです。手こずるかもしれませんが、彼女の助けが必要です。", nil, nil, 0x7026db36, 0x2e21bcfe, 0x639c3012, nil, nil, "...mm" },
  [96931] = { "山を登って", "Cradle of Tranquilityを見下ろす橋の上のCrow Effigyに触れ、Wild GodのJeremanを呼び出す。", "聞け、地を這う者よ。もちろん、我は知性と機知で名高いが、我よりもさらに威厳があり、強大な者がおる。\n\n言うまでもなく、Wild Godsの中で最も賢く、最も狡猾で、最も見目麗しいJeremanのことだ！鳥なら誰もが彼女の名を知っておるし、その知恵は翼の幅をはるかに超える。あの古き石の魔法に何が必要か、彼女ならきっと分かるであろう。\n\n彼女は、お前たち地を這う者がCradle of Tranquilityと呼ぶ場所に巣を構えている。古い橋の上にあるカラスの像に触れれば、姿を現すかもしれん！", nil, nil, 0xceba0759, 0xa576d66f, 0x9c7b7fcc, nil, nil, "...mm" },
  [96939] = { "生と死の均衡", "Wild GodのMarrosisと話す。", "Ketharasの策に加える力の源について、我が良き友の一人が何か思いつくかもしれぬ。\n\n彼はもちろん親しい友だ。そなたのような我が意志の代行者に手を貸せるとなれば、大喜びするであろう！\n\nあの臭い羽の老いぼれは、ここから南の、アンデッドがうようよしている辺りにおる。そなたら定命の者は、Mourning's Restと呼んでいたか？\n\n我が遣わしたと必ず伝えるのだぞ！あやつはきっと喜ぶ……間違いなくな！", nil, nil, 0x41e7f749, 0x22f1ab29, 0x9414b433, nil, nil, "...mm" },
  [96957] = { "骨、愛しき骨", "Sun-Bleached Bonesを$N1個集める。", "聞け、定命の者よ。華々しい仕事には見えぬかもしれぬが、我が翼の下にある者たちは自然の均衡を保つ手助けをしておる。我らは多くの大切な養分を土に還し、新たな命を可能にしているのだ。\n\nこのアンデッドどもがここでの循環を乱し、我が翼の下に身を寄せようとする者たちを追い払ってしまった。そなたが殺戮好きの小さな生き物らしくあちらで暴れているついでに、骨を集めてきてはくれぬか？\n\nこの災いが終わったとき宴を開けるよう、我が子らと従者たちの巣を作り直したいのだ。", nil, nil, 0xd411e8a7, 0x14ee20c3, 0x8da62d90, nil, nil, "...mm" },
  [96959] = { "剣聖のかがり火", "Dae'gunにある2つのかがり火を灯し、Yashiroのもとへ戻る。", "戦だ。\n\n俺が氏族の呼びかけに応じた時には、戦いはもう過ぎ去り、俺の刃に応えたのは灰だけだった。\n\n俺の目的は新たに鍛え直された。\n\nこの山は力を覚えている。その風に乗り、その水に宿る太古の力を。俺はその背骨を歩む資格を得たい。頂への道の途中にある、陥落した砦にたどり着くために。\n\n悪魔どもがこの墓を汚している。お前の隣で戦う前に、お前が戦える者か知らねばならん。2つのかがり火を灯して、俺のところへ戻ってこい。その炎が敵をおびき出す。", nil, nil, 0x6ddccd05, 0x271f18a0, 0x0cf974dc, nil, nil, "...mm" },
  [96964] = { "賢い生き物", "Wild God Renalardと話す。", "隠者が本当にあの小さな策を巣立たせて飛ばしたいのなら、強力な力の源がいるだろうな。崩れることなく、自らを保ち続けられるものが。\n\n<Jeremanは空を見上げ、考えながらくちばしをカチカチと鳴らす。>\n\nああ、そうだ。相談するのにうってつけの賢い生き物を知っておる。北へ行き、そなたら定命の者がDae'gunと呼ぶ、悪魔のいる地へ向かうのだ。そして狐のWild God Renalardを探せ。我らの小さな謎の答えを、あやつなら持っておるであろう。", nil, nil, 0xcb2372fd, 0xfb7c78fb, 0xc6e18bf1, nil, nil, "...mm" },
  [96971] = { "悪魔を出し抜く", "Abandoned Suppliesを$N1個集める。", "なあ、俺の土地をぴょんぴょん跳ね回っているついでに、ひとつ頼まれてくれないか？\n\n戦に勝った後、いろんな軍の多くがさっさと去っていった。どういうわけか、物資の一部は持っていく価値がないと思ったらしい。あるいは、みんな死んじまったか。誰にも分からんさ。\n\nともかく、その物資は俺と子狐たちの役に立つんだ。あいにく、物資があるのはたいてい悪魔のいるところでな。この毛の房を持っていって、悪魔に使って気を逸らし、その隙に道具をいただいてくるといい。", nil, nil, 0x8a1c54ab, 0x3d8fcac2, 0xba6994f0, nil, nil, "...mm" },
  [96978] = { "荒ぶる鹿肉", "Wild GodのKala'thと話す。", "あの忌々しいBlackthorneのドルイドどもが力を握って以来、ここHyjalの力の弱い神々の多くが……はっきり言えば、物事の自然の秩序をひっくり返そうとしてきたのだ。\n\nその最たる者がKala'thだ。\n\n<Jeremanはあきれたように目を回す。>\n\nあの愚かな鹿は、自分と群れを捕食者だと思い込んでいるようだ。またしてもな。\n\n誤解するでないぞ、最初はなかなか愉快だった。だが、そろそろ物事を元の翼に戻す時だ。\n\n彼女のところへ行って話をし、正気に戻せるか試してみてくれ。頼んだぞ。", nil, nil, 0xfb4b81d5, 0x82f85488, 0x6a1b100a, nil, nil, "...mm" },
  [96979] = { "聖なる飲み物", "この先の滝で、Galvinquam Leafsyreの飲み水用のひょうたんを満たす。", "私はCircleのドルイドで、偉大なる世界樹を敬うため長い道を歩んでいます。この登りがどれほど私に求めるかを見誤り、しかもこの斜面に出没する翼あるハンターたちのせいで、用心が欠かせなくなりました。この古い遺跡が身を寄せる場所を与えてくれたので、ありがたく受け入れたのです。\n\nここはささやかな捧げ物にふさわしい場所ですが、生きた水なしに儀式を捧げるべきではありません。よろしければ、この先の滝で私のひょうたんに水を汲んできてください。\n\n戻ったら、あなたが歩いてきた道のこと、そしてその道で何がうごめいているのかを話してください。", nil, nil, 0xcef841cb, 0x6ed72776, 0xca1f2562, nil, nil, "...mm" },
  [96982] = { "初めての騎乗用Kodo", "騎乗用のkodoを見て回り、最初の乗騎を選ぶ。", "ああ、待っていたぞ、{class}。今日、風がそなたを我がもとへ運んできたようだな。kodoを求めて来たのであろう？\n\nkodoは怒ることの少ない気高い獣だ。これほど頼りになる相棒は、なかなか見つかるまい。\n\n今日、そなたは大切な選択をせねばならぬ。そなたとkodoは共に世界を旅することになる。だから、どれがそなたに語りかけてくるかを見極めるのだ。恐れることはない。どれを選ぼうとも、それが正しい選択となろう。\n\nkodoたちを見に行き、選び終えたら我がもとへ戻ってくるがよい。", nil, nil, 0x2f8c7c80, 0x9ca0fd73, 0xb649c7a4, nil, nil, "...mm" },
  [96983] = { "Yashiro's Windwalk", "YashiroとともにDae'gunを戦いながら突き進む。", "お前は有能で、素早く、恐れを知らん。火は悪魔どもを隠れ家から、そしてそれと共に奴らの将軍どもを引きずり出すだろう。奴らは支配を求めてやって来る。だが待っているのは復讐だ。今こそ、山の意志が我らを通して語る時だ。\n\n来い、この地獄の落とし子どもを切り開いて道を作り、奴らの支配を終わらせよう。俺の刃は奴らの隊列を斬り裂きたくて疼いている。", nil, nil, 0x727b69f3, 0x30aead77, 0xc9314578, nil, nil, "...mm" },
  [96984] = { "混乱の中心", "Tarren MillのMagus Wordeen VoidglareのためにCity of DalaranでArcane Moteを集める。", "お前が我々のためを思っているとは限らないが、手が増えるのを断るつもりはない。それに、Dalaranが落ちれば、すべてが道連れになる。お前のUndercityもな。\n\nつまり、お前の後援者も一枚噛みたいと？いいだろう。私の結界を越えられるようにお前の鍵に力を込めてやるから、都市に入れ。中に入ったら、すべてが始まったViolet Citadelで落ち合おう。これだけのことが起きている今、Kirin Torはお前を止める暇もないだろう。\n\n好きなものを漁ればいい。だが何が起きようと、我々の最優先事項は破局を防ぐことだ。", nil, nil, 0x0ac2f4b9, 0xe3ed9b69, 0x6b205a30, nil, nil, "...mm" },
  [96986] = { "墓の騎士", "Tarren MillのMelisaraのために、City of DalaranでAtrexis the Grave Knightを倒して下さい。", "北にあるメイジの都市の地下深くに、我らの同胞を裏切った者がいる。忌まわしい才能を持つ死霊術師だ。奴はKirin Torの目と鼻の先で、不死の軍勢を起こしている。\n\nメイジの都市の運命などどうでもいい、{name}。だがこの墓の騎士は、我々Forsakenが掲げるすべてのものに唾を吐いている。奴を始末しろ。Dark Ladyの手が届かぬ者などいないと、奴に思い知らせてやれ。", nil, nil, 0x9b982b21, 0x24bf35e3, 0x65fb9835, nil, nil, "...mm" },
  [96987] = { "抜け目のない学び", "下水道の入り口近くにいるRexxie Copperclutchのために、City of DalaranからFounding of Dalaranを集めて下さい。", "おやおや、同じ考えの商売人じゃねえか。こんな物騒なときにDalaranに忍び込むとはね。チッチッ。\n\nまさに俺好みの{race}だ！\n\nここのメイジのお友達が手一杯なうちに、「置き忘れられた」お宝でも見つけようじゃないか。奴らにはご大層な秘術の魔法専用の図書館がいくつもある。秘密の書物を一冊持ってきてくれりゃ、いい値で売りさばける。儲けは山分けだ。\n\nおいおい、そんな目で見るなよ。お前さんだって、ここへ社会見学に来たわけじゃないだろ。乗るのか、乗らないのか？", nil, nil, 0xcb4d2d84, 0xc41dad65, 0x159f4617, nil, nil, "...mm" },
  [96988] = { "力の源", "UndercityのDoctor Martin Felbenのために、City of DalaranでCracked Sentry Coreを$N1個集めて下さい。", "Dalaranの都市が自らの構造体に包囲されている今こそ、そうだな、いくつかサンプルを「拝借」する絶好の機会だ。\n\n秘術の力で動くabominationsの軍勢を想像してみろ。Dark Ladyも私の錬金術の腕を認めざるを得なくなる。Royal Apothecary Societyの長に任じてくださるかもしれん。\n\n都市へ行き、構造体のコアを見つけてこい。素直に差し出すとは思えんから、必要なことをしろ。", nil, nil, 0x64b20fc1, 0x8337ed29, 0xa537f845, nil, nil, "...mm" },
  [96989] = { "初めての騎乗用Raptor", "騎乗用のraptorsを見て回り、最初の騎乗動物を選ぶ。", "よう、相棒！今日はお前さんにとって大事な日みてえだな。こいつら獰猛な生き物の手綱を握る準備ができたと思ってんのか、ん？\n\nたいていの奴は、この獣どもがどれだけ賢くて凶暴か、甘く見てるんだ。一度絆を結んじまえば、これ以上いい、速い、恐ろしい相棒は見つからねえよ。\n\nだからよ、お前さんには大事な選択がある。お前さんのraptorとお前さんは一緒に世界を旅することになるし、raptorの方もお前さんを選び返さなきゃならねえ。\n\n行って見てきな。選んだら俺んとこに戻ってこい。", nil, nil, 0x5d01635c, 0xd621c0a6, 0xee32bad6, nil, nil, "...mm" },
  [96991] = { "道中の手助け", "Galvinquam's BelongingsをSummitのMarn Euhronのもとへ届ける。", "おっしゃる通り、ここから先の登りはさらに険しくなります。空の荷物でさえ、疲れた脚には重くのしかかるものです。旅の方、もう一つ親切をお願いしたいのです。私の余分な荷物を預かって、Summitまで運んでいってください。そこではMarn Euhronが、Nordrassilの近くに足掛かりを取り戻す手助けをしています。\n\nここでの儀式を終えたら、私も自分の足取りで後を追います。着いたら彼から荷物を受け取り、彼らの仕事を手伝います。こうすれば、私たち二人とも旅路と山の恵みを敬うことになるでしょう。", nil, nil, 0x0487ac9f, 0x9af8f93c, 0x274078c3, nil, nil, "...mm" },
  [96992] = { "補給", "Cradle of Tranquilityの焼けた建物を調べてMetal Bracketsを$N1個とNailsを$N2本見つけ、HyjalのJohun \"Punchy\" Dillasのもとへ戻る。", "なあ、基本を始めるだけの道具は詰めてくれたんだが、留め具の材料はいつだって足りないんだ。縄を巻くのも、この手じゃ限度があってな。\n\n備えがあることよりも、工夫できることの方がさらにいい。\n\n空の袋を持って、ここから南西、Cradle of Tranquilityの周りにあるallianceの建物の焼け跡へ行ってくれ。灰の中で見つかるだけのnailsとbracketsを、袋に詰めてきてくれ。", nil, nil, 0x9e2e3b44, 0x4554daea, 0xb9dd50a4, nil, nil, "...mm" },
  [96994] = { "初めての騎乗用狼", "騎乗用の狼を見て回り、最初の騎乗動物を選ぶ。", "Lok'tar、{class}。初めての狼と絆を結びに来たのか？よし。\n\nオークとその狼の絆ほど強い絆はない。奴らはただの乗騎ではない。生涯の相棒であり、友なのだ。\n\n我らの絆は見栄で選ぶものではない。いや、オークと狼はそれぞれ、ただの買い物を超えた特別な絆を結ぶ。\n\nお前が奴らを選ぶのと同じだけ、奴らもお前を選ぶ。会えば分かる。\n\n行って、どの狼がお前に語りかけるか見つけてこい。答えが出たら戻ってこい。", nil, nil, 0x312823d3, 0x8e279f41, 0xc1cfe1ad, nil, nil, "...mm" },
  [96996] = { "初めての騎乗用Galestrider", "騎乗用のstriderを見て回り、最初の乗騎を選ぶ。", "訓練を終えた今、風はそなたが最初のstriderと絆を結ぶことを望んでいるようだ。\n\nこのgalestriderたちは、我らの祖先が何世代にもわたって乗ってきたものだ。か細くほっそりとした見た目に反して、揺るがぬ勇猛な乗騎なのだ。\n\nそなたとstriderは共に世界を巡ることになる。だから、大切な選択をせねばならぬ。恐れることはない。どれを選ぼうとも、それが正しい選択となろう。\n\nstriderたちを見に行き、選び終えたら我がもとへ戻ってくるがよい。", nil, nil, 0x0451b7f8, 0xd4f44937, 0x11448014, nil, nil, "...mm" },
  [96997] = { "生前と変わらぬ死後の愛馬", "騎乗用のアンデッドの馬を見て回り、最初の乗騎を選ぶ。", "ようこそ、{class}。今日、何がお前をこの厩舎へ連れてきたのか、察しはつく。\n\n乗騎を探しているのなら、来る場所は合っている。ただし言っておくが、アンデッドの馬に乗るのは気の弱い者には向かない。\n\nだからこそ、お前は大切な選択をしなければならない。良くも悪くも、お前とアンデッドの馬は共に世界を旅することになる。恐れることはない。どれを選ぼうと、それが正しい選択になる。\n\nアンデッドの馬たちを見に行き、選び終えたら私のところへ戻ってこい。", nil, nil, 0xcea878f9, 0x3be62de1, 0xacfdae3d, nil, nil, "...mm" },
  [96998] = { "部族の色", "War Paint Wrapを、それに見覚えがありそうな人のもとへ持っていく。", "まだ投げ槍を握りしめている骸骨には、トロールの首狩りの紛れもない特徴がある。\n\nその骨ばった手の片方には、トロールの文字と、Darkspearの色の顔料の染みで飾られた革の包みがある。戦化粧を施すのに使われた化粧袋に違いない。\n\nDarkspear族の者なら、この神聖な革に記された文字が分かるかもしれない。", nil, nil, 0xfbe8a5d2, 0xa798a01b, 0x91d746c5, nil, nil, "...mm" },
  [96999] = { "布の返却", "War Paint WrapをSen'jin Villageの誰かのもとへ持っていく。", "これを身に着けてた奴は、目的を持って戦ってた。それにSen'jinは小さな村だ……血も身内も近いんだ。\n\n故郷の誰かが、この包みを……そしてこれを持ってたウォリアーを探してるはずだ。\n\nEcho Islesへ行くなら、この包みを持っていきな。Sen'jinに返してやってくれ。誰の物か、あいつらなら分かる……そして、返してくれたお前さんを称えるだろうよ。", nil, nil, 0x8926bb2c, 0x6e7f2ad0, 0x8c6bab1d, nil, nil, "...mm" },
})
